#[test]
fn lane_consensus_key_role_is_exact() {
    assert_eq!(
        consensus_key_role_for_lane(LaneId::SINGLE),
        ConsensusKeyRole::Validator
    );
    assert_eq!(
        consensus_key_role_for_lane(LaneId::new(1)),
        ConsensusKeyRole::Committee
    );
    assert_eq!(
        consensus_key_role_for_lane(LaneId::new(42)),
        ConsensusKeyRole::Committee
    );
}
macro_rules! let_row { ($($tokens:tt)*) => { let $($tokens)*; }; }
macro_rules! state_test {
    (consensus_stack $name:ident $($body:tt)*) => {
        #[test]
        fn $name() {
            let handle = crate::sumeragi::threads::sumeragi_thread_builder(concat!(
                "state-consensus-", stringify!($name),
            ))
            .spawn(move || { $($body)* })
            .expect("spawn State integration test on the production consensus stack");
            if let Err(payload) = handle.join() {
                std::panic::resume_unwind(payload);
            }
        }
    };
    (sync $name:ident $($body:tt)*) => {
        #[test]
        fn $name() { $($body)* }
    };
    (result $name:ident $($body:tt)*) => {
        #[test]
        fn $name() -> Result<()> { $($body)* }
    };
    (large_stack $name:ident $($body:tt)*) => {
        #[test]
        fn $name() {
            run_state_test_on_large_stack(stringify!($name), || { $($body)* });
        }
    };
}

fn run_state_test_on_large_stack(name: &'static str, test: impl FnOnce() + Send + 'static) {
    let handle = std::thread::Builder::new()
        .name(name.to_owned())
        .stack_size(16 * 1024 * 1024)
        .spawn(test)
        .expect("spawn state test with an explicit stack budget");
    if let Err(payload) = handle.join() {
        std::panic::resume_unwind(payload);
    }
}

