fn test_da_pin_intent(
    network_id: NetworkId,
    lane_id: LaneId,
    epoch: u64,
    sequence: u64,
    storage_ticket: StorageTicketId,
    manifest_hash: ManifestDigest,
) -> DaPinIntent {
    crate::da::signed_test_pin_intent(
        crate::da::signed_test_ingest_authorization(
            network_id,
            &ALICE_KEYPAIR,
            lane_id,
            epoch,
            sequence,
            1,
        ),
        &ALICE_KEYPAIR,
        storage_ticket,
        manifest_hash,
        None,
    )
}
