fn world_with_privacy_tightenings(
    protocol_scheduled_at_height: u64,
    protocol_effective_at_height: u64,
) -> (
    World,
    iroha_data_model::privacy::PrivacyConsensusLimitsV1,
    iroha_data_model::privacy::PrivacyProtocolActivationLimitsV1,
) {
    use iroha_data_model::privacy::{
        PrivacyConsensusPolicyTighteningV1, PrivacyConsensusPolicyV1, PrivacyProposedLifecycleV1,
        PrivacyProtocolIdV1, PrivacyProtocolLifecycleV1, PrivacyProtocolLimitsTighteningV1,
    };
    let mut world = World::default();
    let current_limits = iroha_data_model::privacy::PrivacyConsensusLimitsV1::taira_default();
    let mut next_limits = current_limits;
    next_limits.max_actions_per_block -= 1;
    next_limits.retained_root_count -= 1;
    world.privacy_consensus_policy = mv::cell::Cell::new(PrivacyConsensusPolicyV1 {
        current_limits,
        pending_tightening: Some(PrivacyConsensusPolicyTighteningV1 {
            scheduled_at_height: 100,
            effective_at_height: 400,
            next_limits,
        }),
    });
    let_row! { mut activation = crate::privacy_profiles::compiled_privacy_profile_v1( PrivacyProtocolIdV1::VeRangeTransparentRangeV1, ) .expect("compiled VeRange profile") .activation_record(PrivacyProtocolLifecycleV1::Proposed( PrivacyProposedLifecycleV1 { proposed_at_height: 100, }, )) };
    let mut next_protocol_limits = activation.protocol_limits;
    let_row! { iroha_data_model::privacy::PrivacyProtocolActivationLimitsV1::VeRangeTransparentRangeV1( ref mut limits, ) = next_protocol_limits else { unreachable!("VeRange compiled profile") } };
    limits.max_aggregation_count -= 1;
    activation.pending_protocol_limits_tightening = Some(PrivacyProtocolLimitsTighteningV1 {
        scheduled_at_height: protocol_scheduled_at_height,
        effective_at_height: protocol_effective_at_height,
        next_limits: next_protocol_limits,
    });
    world.privacy_activations.insert(
        crate::privacy_state::PrivacyActivationKeyV1::new(
            PrivacyProtocolIdV1::VeRangeTransparentRangeV1,
        ),
        activation,
    );
    (world, next_limits, next_protocol_limits)
}
state_test! { sync privacy_policy_and_protocol_tightenings_apply_atomically_at_block_start
    use iroha_data_model::privacy::{
        PrivacyProtocolActivationLimitsV1, PrivacyProtocolIdV1, PrivacyProtocolLifecycleV1,
    };
    let (world, next_limits, next_protocol_limits) = world_with_privacy_tightenings(100, 400);
    let_row! { state = State::new( world, Kura::blank_kura_for_testing(), LiveQueryStore::start_test(), ) };
    let header = BlockHeader::new(nonzero!(400_u64), None, None, 0, 0);
    let mut block = state.block(header);
    let policy = *block.world.privacy_consensus_policy.get();
    assert_eq!(policy.current_limits, next_limits);
    assert_eq!(policy.pending_tightening, None);
    assert_eq!(block.privacy_budget_in_block.limits(), &next_limits);
    assert_eq!(block.privacy_budget_in_block.actions(), 0);
    assert_eq!(block.privacy_budget_in_block.bytes(), 0);
    let_row! { key = crate::privacy_state::PrivacyActivationKeyV1::new( PrivacyProtocolIdV1::VeRangeTransparentRangeV1, ) };
    let_row! { activation = *block .world .privacy_activations .get(&key) .expect("activation with updated limits") };
    assert_eq!(activation.protocol_limits, next_protocol_limits);
    assert_eq!(activation.pending_protocol_limits_tightening, None);
    assert!(matches!(
        activation.lifecycle,
        PrivacyProtocolLifecycleV1::Proposed(_)
    ), "a protocol-limit schedule must not activate a pending proposal");
    assert!(matches!(
        activation.protocol_limits,
        PrivacyProtocolActivationLimitsV1::VeRangeTransparentRangeV1(_)
    ));
    {
        let mut transaction = block.transaction();
        transaction
            .reserve_privacy_action(0, 1)
            .expect("one action under tightened block budget");
        transaction.apply();
    }
    let transaction = block.transaction();
    assert!(
        transaction.preflight_privacy_action(0, 1).is_err(),
        "the due max-actions-per-block tightening must govern this exact block"
    );
}
state_test! { sync missed_protocol_schedule_rolls_back_a_due_policy_start_hook
    use iroha_data_model::privacy::PrivacyProtocolIdV1;
    use std::panic::{AssertUnwindSafe, catch_unwind};
    let (world, _, _) = world_with_privacy_tightenings(99, 399);
    let original_policy = *world.privacy_consensus_policy.view().get();
    let_row! { activation_key = crate::privacy_state::PrivacyActivationKeyV1::new( PrivacyProtocolIdV1::VeRangeTransparentRangeV1, ) };
    let_row! { original_activation = *world .privacy_activations .view() .get(&activation_key) .expect("scheduled activation") };
    let_row! { state = State::new( world, Kura::blank_kura_for_testing(), LiveQueryStore::start_test(), ) };
    let header = BlockHeader::new(nonzero!(400_u64), None, None, 0, 0);
    let_row! { error = catch_unwind(AssertUnwindSafe(|| { let _block = state.block(header); })) .expect_err("missed protocol schedule must abort block construction") };
    let_row! { panic_text = error .downcast_ref::<String>() .map(String::as_str) .or_else(|| error.downcast_ref::<&str>().copied()) .unwrap_or("") };
    assert!(panic_text.contains("missed"), "{panic_text}");
    assert_eq!(
        state.world.privacy_consensus_policy.view().get(),
        &original_policy,
        "a failed later start hook must not publish the earlier due policy write"
    );
    assert_eq!(
        state.world.privacy_activations.view().get(&activation_key),
        Some(&original_activation),
        "a failed start hook must leave the base activation unchanged"
    );
}
state_test! { sync failed_pristine_stage_skips_start_effects_and_releases_overlay
    use iroha_data_model::privacy::PrivacyProtocolIdV1;

    let (world, next_limits, next_protocol_limits) = world_with_privacy_tightenings(100, 400);
    let original_policy = *world.privacy_consensus_policy.view().get();
    let activation_key = crate::privacy_state::PrivacyActivationKeyV1::new(
        PrivacyProtocolIdV1::VeRangeTransparentRangeV1,
    );
    let original_activation = *world
        .privacy_activations
        .view()
        .get(&activation_key)
        .expect("scheduled activation");
    let state = State::new(
        world,
        Kura::blank_kura_for_testing(),
        LiveQueryStore::start_test(),
    );
    let header = BlockHeader::new(nonzero!(400_u64), None, None, 0, 0);
    let error = match state.block_with_pristine_stage(header, |block| {
        assert!(!block.start_of_block_effects_applied);
        assert_eq!(block.world.privacy_consensus_policy.get(), &original_policy);
        assert_eq!(
            block.world.privacy_activations.get(&activation_key),
            Some(&original_activation),
            "the pristine stage must precede due privacy effects",
        );
        let mut staged_activation = original_activation;
        // If construction continues past the failed stage, the start hook must
        // reject this missed schedule instead of silently discarding its writes.
        staged_activation
            .pending_protocol_limits_tightening
            .as_mut()
            .expect("pending protocol tightening")
            .effective_at_height = 399;
        block
            .world
            .privacy_activations
            .insert(activation_key, staged_activation);
        Err("rejected pristine stage")
    }) {
        Ok(_) => panic!("a rejected pristine stage must not construct a block"),
        Err(error) => error,
    };
    assert!(matches!(error, StateBlockStartError::Stage("rejected pristine stage")));
    assert_eq!(state.world.privacy_consensus_policy.view().get(), &original_policy);
    assert_eq!(
        state.world.privacy_activations.view().get(&activation_key),
        Some(&original_activation),
        "a failed stage must discard its activation write",
    );

    // Taking a new block scope also proves that failure released every overlay lock.
    let block = state.block(header);
    assert!(block.start_of_block_effects_applied);
    assert_eq!(block.world.privacy_consensus_policy.get().current_limits, next_limits);
    assert_eq!(block.world.privacy_consensus_policy.get().pending_tightening, None);
    assert_eq!(block.privacy_budget_in_block.limits(), &next_limits);
    let activation = block
        .world
        .privacy_activations
        .get(&activation_key)
        .expect("activation survives the discarded stage");
    assert_eq!(activation.protocol_limits, next_protocol_limits);
    assert_eq!(activation.pending_protocol_limits_tightening, None);
    drop(block);
    assert_eq!(state.world.privacy_consensus_policy.view().get(), &original_policy);
    assert_eq!(
        state.world.privacy_activations.view().get(&activation_key),
        Some(&original_activation),
        "dropping a successful block scope must also discard its start effects",
    );
}
state_test! { sync privacy_action_budget_is_transactional_contiguous_and_fail_closed
    let state = blank_state();
    let header = BlockHeader::new(nonzero!(1_u64), None, None, 0, 0);
    let mut block = state.block(header);
    let limits = iroha_data_model::privacy::PrivacyConsensusLimitsV1::taira_default();
    {
        let mut transaction = block.transaction();
        assert_eq!(transaction.privacy_budget_for_testing(), (0, 0, 0, 0));
        assert_eq!(transaction.next_privacy_action_index(), 0);
        let_row! { skipped_preflight = transaction .preflight_privacy_action(1, 64) .expect_err("skipped index preflight") };
        let_row! { skipped_reservation = transaction .reserve_privacy_action(1, 64) .expect_err("skipped index reservation") };
        assert_eq!(
            skipped_preflight.to_string(),
            skipped_reservation.to_string(),
            "preflight and reservation must share the exact rejection path"
        );
        let_row! { zero_preflight = transaction .preflight_privacy_action(0, 0) .expect_err("zero-byte preflight") };
        let_row! { zero_reservation = transaction .reserve_privacy_action(0, 0) .expect_err("zero-byte reservation") };
        assert_eq!(zero_preflight.to_string(), zero_reservation.to_string());
        let oversized_bytes = u64::from(limits.max_action_bytes) + 1;
        let_row! { oversized_preflight = transaction .preflight_privacy_action(0, oversized_bytes) .expect_err("oversized preflight") };
        let_row! { oversized_reservation = transaction .reserve_privacy_action(0, oversized_bytes) .expect_err("oversized reservation") };
        assert_eq!(
            oversized_preflight.to_string(),
            oversized_reservation.to_string()
        );
        assert_eq!(
            transaction.privacy_budget_for_testing(),
            (0, 0, 0, 0),
            "rejected preflights and reservations must not consume local or staged block budget"
        );
        transaction
            .preflight_privacy_action(0, 64)
            .expect("first contiguous action preflight");
        assert_eq!(
            transaction.privacy_budget_for_testing(),
            (0, 0, 0, 0),
            "successful preflight must remain non-mutating"
        );
        transaction
            .reserve_privacy_action(0, 64)
            .expect("unchanged state must make reservation agree with preflight");
        assert_eq!(transaction.next_privacy_action_index(), 1);
        assert_eq!(transaction.privacy_budget_for_testing(), (1, 64, 1, 64));
        assert!(transaction.preflight_privacy_action(0, 32).is_err());
        assert!(transaction.preflight_privacy_action(2, 32).is_err());
        let_row! { exhausted_preflight = transaction .preflight_privacy_action(1, 32) .expect_err("the compiled first release permits one privacy action per transaction") };
        let_row! { exhausted_reservation = transaction .reserve_privacy_action(1, 32) .expect_err("the compiled first release permits one privacy action per transaction") };
        assert_eq!(
            exhausted_preflight.to_string(),
            exhausted_reservation.to_string(),
            "the compiled first release permits one privacy action per transaction"
        );
        assert_eq!(
            transaction.privacy_budget_for_testing(),
            (1, 64, 1, 64),
            "duplicate, skipped, and over-limit actions must not consume budget"
        );
        // Dropping the transaction exercises rollback of the entire
        // staged reservation set.
    }
    assert_eq!(block.privacy_budget_in_block.actions(), 0);
    assert_eq!(block.privacy_budget_in_block.bytes(), 0);
    {
        let mut transaction = block.transaction();
        assert_eq!(transaction.next_privacy_action_index(), 0);
        transaction
            .reserve_privacy_action(0, 48)
            .expect("fresh transaction restarts its action index");
        transaction.apply();
    }
    assert_eq!(block.privacy_budget_in_block.actions(), 1);
    assert_eq!(block.privacy_budget_in_block.bytes(), 48);
    {
        let mut transaction = block.transaction();
        assert_eq!(
            transaction.privacy_budget_for_testing(),
            (0, 0, 1, 48),
            "a new transaction inherits committed block usage only"
        );
        transaction
            .reserve_privacy_action(0, 16)
            .expect("another transaction reserves independently");
        transaction.apply();
    }
    assert_eq!(block.privacy_budget_in_block.actions(), 2);
    assert_eq!(block.privacy_budget_in_block.bytes(), 64);
    {
        let mut transaction = block.transaction();
        assert_eq!(
            transaction.privacy_budget_for_testing(),
            (0, 0, 2, 64),
            "the third transaction sees the complete committed block budget"
        );
        let_row! { exhausted_preflight = transaction .preflight_privacy_action(0, 16) .expect_err("the compiled first release permits two privacy actions per block") };
        assert_eq!(
            transaction.privacy_budget_for_testing(),
            (0, 0, 2, 64),
            "block-limit preflight must not consume transaction or block budget"
        );
        let_row! { exhausted_reservation = transaction .reserve_privacy_action(0, 16) .expect_err("the compiled first release permits two privacy actions per block") };
        assert_eq!(
            exhausted_preflight.to_string(),
            exhausted_reservation.to_string(),
            "preflight and final reservation must not diverge at the block boundary"
        );
        assert_eq!(
            transaction.privacy_budget_for_testing(),
            (0, 0, 2, 64),
            "a block-limit rejection must not consume transaction or block budget"
        );
    }
    assert_eq!(block.privacy_budget_in_block.actions(), 2);
    assert_eq!(block.privacy_budget_in_block.bytes(), 64);
}
state_test! { sync privacy_action_budget_accepts_exact_byte_boundary_and_rejects_one_byte_over
    let state = blank_state();
    let header = BlockHeader::new(nonzero!(1_u64), None, None, 0, 0);
    let mut block = state.block(header);
    let_row! { max = u64::from( iroha_data_model::privacy::PrivacyConsensusLimitsV1::taira_default().max_action_bytes, ) };
    let mut transaction = block.transaction();
    let_row! { overflow_preflight = transaction .preflight_privacy_action(0, max + 1) .expect_err("one byte above the action cap") };
    let_row! { overflow_reservation = transaction .reserve_privacy_action(0, max + 1) .expect_err("one byte above the action cap") };
    assert_eq!(
        overflow_preflight.to_string(),
        overflow_reservation.to_string()
    );
    assert_eq!(transaction.privacy_budget_for_testing(), (0, 0, 0, 0));
    transaction
        .preflight_privacy_action(0, max)
        .expect("exact inclusive action-byte boundary");
    assert_eq!(
        transaction.privacy_budget_for_testing(),
        (0, 0, 0, 0),
        "boundary preflight is read-only"
    );
    transaction
        .reserve_privacy_action(0, max)
        .expect("reservation must agree with successful boundary preflight");
    assert_eq!(transaction.privacy_budget_for_testing(), (1, max, 1, max));
}
fn nondefault_pre_genesis_dataspace_fixture(
    configured: bool,
) -> iroha_config::parameters::actual::Nexus {
    let secondary = LaneConfig {
        id: LaneId::new(1),
        dataspace_id: DataSpaceId::new(7),
        alias: "fixture-dataspace".to_owned(),
        ..LaneConfig::default()
    };
    let catalog = LaneCatalog::new(nonzero!(2_u32), vec![LaneConfig::default(), secondary])
        .expect("two configured lanes");
    let dataspaces = DataSpaceCatalog::new(vec![
        DataSpaceMetadata::default(),
        DataSpaceMetadata {
            id: DataSpaceId::new(7),
            alias: "fixture-dataspace".to_owned(),
            description: Some("nondefault physical test dataspace".to_owned()),
            fault_tolerance: 1,
        },
    ])
    .expect("two configured dataspaces");
    let mut nexus = iroha_config::parameters::actual::Nexus {
        lane_config: RuntimeLaneConfig::from_catalog(&catalog),
        lane_catalog: catalog,
        dataspace_catalog: dataspaces,
        ..Default::default()
    };
    if configured {
        nexus.configured_lane_catalog = nexus.lane_catalog.clone();
        nexus.configured_dataspace_catalog = nexus.dataspace_catalog.clone();
    } else {
        assert_ne!(nexus.configured_dataspace_catalog, nexus.dataspace_catalog);
    }
    nexus
}

fn assert_pre_genesis_dataspace_fixture(
    state: &State,
    requested: &iroha_config::parameters::actual::Nexus,
) {
    let installed = state.nexus_snapshot();
    assert_eq!(installed.lane_catalog, requested.lane_catalog);
    assert_eq!(installed.configured_lane_catalog, requested.lane_catalog);
    assert_eq!(installed.dataspace_catalog, requested.dataspace_catalog);
    assert_eq!(
        installed.configured_dataspace_catalog,
        requested.dataspace_catalog
    );
    assert_eq!(installed.routing_policy, requested.routing_policy);
    assert_eq!(
        state.view().world().dataspace_catalog(),
        &requested.dataspace_catalog
    );
    assert_eq!(state.committed_height(), 0);
    assert_eq!(
        state
            .kura
            .exact_durable_blocks_count()
            .expect("durable height"),
        0
    );
    assert!(
        runtime_catalog_from_world(&state.world.view())
            .expect("protected overlay")
            .is_none()
    );
    assert_eq!(state.lane_incarnations_snapshot().len(), 2);
}

