#[test]
fn test_nexus_fixture_constructor_opens_custom_primary_without_archiving_default_segment() {
    let_row! { custom_primary = LaneConfig { alias: "custom-primary".to_owned(), ..LaneConfig::default() } };
    let_row! { custom_catalog = LaneCatalog::new(nonzero!(1_u32), vec![custom_primary]).expect("custom lane catalog") };
    let_row! { state = State::new_with_pre_genesis_nexus_for_testing( World::default(), iroha_config::parameters::actual::Nexus { lane_catalog: custom_catalog, ..Default::default() }, LiveQueryStore::start_test(), ) };
    state
        .lane_manifests
        .read()
        .ensure_lane_ready(LaneId::SINGLE)
        .expect("custom primary test lane must have an authenticated manifest");
    let store_root = state.kura.store_root();
    let nexus = state.nexus_snapshot();
    let primary = state
        .lane_storage_identity(LaneId::SINGLE)
        .expect("authenticated primary identity");
    assert!(primary.blocks_dir(&store_root).is_dir());
    let configured_primary =
        fixture_static_storage_identity(&state, &nexus.lane_catalog, LaneId::SINGLE);
    assert_ne!(
        nexus.lane_config.primary().kura_segment,
        RuntimeLaneConfig::default().primary().kura_segment
    );
    assert_eq!(
        primary, configured_primary,
        "the original configured alias binds the exact initial primary instance"
    );
    assert_ne!(
        primary,
        fixture_static_storage_identity(&state, &LaneCatalog::default(), LaneId::SINGLE),
        "a different initial consensus alias is a different genesis configuration"
    );
    assert_eq!(
        std::fs::read_dir(store_root.join("blocks/instances"))
            .unwrap()
            .count(),
        1
    );
    assert!(
        !store_root.join("retired").exists(),
        "opening a fixture at its authoritative primary must not archive synthetic default geometry"
    );
}
#[test]
fn test_nexus_fixture_constructor_matches_configured_primary_replay_lineage() {
    let secondary = LaneConfig {
        id: LaneId::new(1),
        alias: "secondary".to_owned(),
        ..LaneConfig::default()
    };
    let configured_catalog =
        LaneCatalog::new(nonzero!(2_u32), vec![LaneConfig::default(), secondary])
            .expect("two-lane configured catalog");
    let primary_replay_catalog = LaneCatalog::new(
        configured_catalog.lane_count(),
        vec![configured_catalog.lanes()[0].clone()],
    )
    .expect("configured primary replay catalog");
    let expected_primary =
        derive_static_lane_incarnations(&primary_replay_catalog)[&LaneId::SINGLE];
    let complete_static = derive_static_lane_incarnations(&configured_catalog);
    assert_ne!(
        expected_primary,
        complete_static[&LaneId::SINGLE],
        "the regression requires a catalog whose primary-only and complete static identities differ"
    );

    let state = State::new_with_pre_genesis_nexus_for_testing(
        World::default(),
        iroha_config::parameters::actual::Nexus {
            lane_catalog: configured_catalog,
            ..Default::default()
        },
        LiveQueryStore::start_test(),
    );
    let lineage = state.lane_incarnation_lineage_snapshot();
    assert_eq!(lineage.len(), 2);
    assert_eq!(lineage[&LaneId::SINGLE].generation, 0);
    assert_eq!(lineage[&LaneId::SINGLE].incarnation, expected_primary);
    assert_eq!(lineage[&LaneId::new(1)].generation, 0);
    assert_eq!(
        lineage[&LaneId::new(1)].incarnation,
        complete_static[&LaneId::new(1)]
    );
}
