state_test! { sync trigger_batch_contract_calls_advance_nft_sequence
    let manifest_signing =
        crate::manifest_signing_test_support::ManifestSigningFixture::new();
    use iroha_data_model::{
        events::execute_trigger::ExecuteTriggerEvent,
        transaction::{ExecutableBatchItem, executable::ContractInvocation},
    };
    use iroha_test_samples::ALICE_KEYPAIR;
    let_row! { (program, manifest) = kotodama_lang::compiler::Compiler::new() .compile_source_with_manifest( r"
seiyaku SequentialNfts { permission CanInvokeContractEntrypoint;
  kotoage fn run() authorize(CanInvokeContractEntrypoint) {
ledger::nft::create_for_all_users();
  }
}
", ) .expect("compile sequential NFT contract") };
    let authority = ALICE_ID.clone();
    let code_hash = ivm::contract_code_hash(&program);
    let initial_world = World::with(
        [Domain::new(iroha_genesis::GENESIS_DOMAIN_ID.clone()).build(&authority)],
        [Account::new(authority.clone()).build(&authority)],
        [],
    );
    let state = authenticate_trigger_fixture(State::new(
        initial_world, Kura::blank_kura_for_testing(), LiveQueryStore::start_test(),
    ));
    let_row! { contract_address = iroha_data_model::smart_contract::ContractAddress::derive(
        state.network_id_ref(), &authority, 95, DataSpaceId::UNIVERSAL,
    ).expect("derive sequential NFT contract address") };
    let contract_authority = contract_address.subject_id();
    let header = trigger_component_block(&state, 2).as_ref().header();
    let mut state_block = state.block(header);
    let mut state_transaction = state_block.transaction_for_callback_testing();
    state_transaction.world.domains.insert(
        iroha_genesis::GENESIS_DOMAIN_ID.clone(),
        Domain::new(iroha_genesis::GENESIS_DOMAIN_ID.clone()).build(&contract_authority),
    );
    Register::account(Account::new(contract_authority.clone()))
        .execute(&authority, &mut state_transaction).expect("register exact native-network contract subject");
    let_row! { entrypoint_permission: Permission = iroha_executor_data_model::permission::smart_contract::CanUseContractPermission {
        contract: contract_address.clone(), permission: "CanInvokeContractEntrypoint".parse().expect("valid contract permission name"),
    }.into() };
    state_transaction.world.account_permissions.insert(
        contract_authority.clone(), BTreeSet::from([entrypoint_permission]),
    );
    let artifact = iroha_data_model::smart_contract::ContractArtifactId::new(DataSpaceId::UNIVERSAL, code_hash);
    state_transaction.world.contract_code.insert(artifact, program);
    state_transaction.world.contract_manifests.insert(artifact, manifest.try_signed(manifest_signing.context(), manifest_signing.max_frame_bytes(), &ALICE_KEYPAIR).expect("sign bounded fixture manifest"));
    // The contract-call fixture needs a canonical active lifecycle and bound
    // subject, not an orphan instance entry rejected by State initialization.
    state_transaction.world.bind_active_contract_subject_for_testing(
        contract_address.clone(),
        code_hash,
    );
    let_row! { invocation = ContractInvocation { contract_address, expected_code_hash: code_hash, entrypoint: "run".to_owned(), arguments: None, } };
    let_row! { executable = ExecutableRef::Batch(ConstVec::from(vec![ ExecutableBatchItem::ContractCall(invocation.clone()), ExecutableBatchItem::ContractCall(invocation), ])) };
    let trigger_id: TriggerId = "sequential_nft_batch".parse().expect("valid trigger id");
    let_row! { event = ExecuteTriggerEvent { trigger_id: trigger_id.clone(), authority: contract_authority.clone(), args: Json::default(), } };
    let accounts = state_transaction.accounts_snapshot();
    let nft_seq_base = 100_u64;
    state_transaction
        .execute_trigger(
            &trigger_id,
            &contract_authority,
            &executable,
            event.into(),
            0,
            Some(nft_seq_base),
        )
        .expect("both contract-call items must use disjoint NFT sequences");
    let mut expected_sequence = nft_seq_base;
    let mut expected_nfts = Vec::new();
    for _ in 0..2 {
        for account in accounts.iter().take(256) {
            let_row! { name = format!( "nft_number_{}_for_{}", expected_sequence, hex::encode(HashOf::new(account).as_ref()) ) .parse() .expect("fixture account produces a valid NFT name") };
            expected_nfts.push(NftId::of(iroha_genesis::GENESIS_DOMAIN_ID.clone(), name));
            expected_sequence = expected_sequence
                .checked_add(1)
                .expect("fixture NFT sequence does not overflow");
        }
    }
    assert_eq!(
        state_transaction.world.nfts.iter().count(),
        expected_nfts.len(),
        "each contract-call item must register its own NFT range"
    );
    for nft_id in expected_nfts {
        assert!(
            state_transaction.world.nfts.get(&nft_id).is_some(),
            "missing NFT from the advanced sequence: {nft_id}"
        );
    }
}
