fn autoscale_storage_state_for_testing(
    kura: Arc<Kura>,
    query_handle: crate::query::store::LiveQueryStoreHandle,
) -> State {
    let constructor_world = World::default();
    let mut state = State::try_new(
        constructor_world
            .sccp_committee_generations
            .allocation_budget()
            .clone(),
        constructor_world,
        kura,
        query_handle,
        #[cfg(feature = "telemetry")]
        <_>::default(),
    )
    .expect("construct autoscale State before provisioning lane instances");
    // Durable identity must authorize the initial physical instance before
    // test defaults install markers or a lifecycle transition can reuse it.
    state
        .prepare_configured_primary_geometry_anchor(&LaneCatalog::default())
        .expect("authenticate the configured primary autoscale instance");
    state
        .restore_kura_lane_segments_before_startup_replay()
        .expect("restore the authenticated primary autoscale geometry");
    state.install_active_lane_markers_for_tests();
    state.configure_test_runtime_defaults();
    state
}
macro_rules! autoscale_storage_fixture {
    ($temp_dir:ident, $store_root:ident, $cold_root:ident, $kura:ident, $query:ident) => {
        let $temp_dir = tempfile::tempdir().expect("temp dir");
        let $store_root = $temp_dir.path().join("kura");
        let $cold_root = $temp_dir.path().join("cold");
        let initial_config = RuntimeLaneConfig::default();
        let $kura = strict_kura_for_testing($store_root.clone(), &initial_config);
        let $query = LiveQueryStore::start_test();
    };
}
fn authenticated_kura_for_testing(
    store_root: std::path::PathBuf,
    configured_catalog: &LaneCatalog,
) -> Arc<Kura> {
    let kura_cfg = strict_kura_config_for_testing(store_root);
    let lane_config = RuntimeLaneConfig::from_catalog(configured_catalog);
    let_row! { (kura, _) = Kura::new_with_configured_lane_catalog(&kura_cfg, &lane_config, configured_catalog) .expect("init authenticated configured Kura") };
    kura
}
fn install_existing_nexus_geometry_for_test(
    state: &State,
    mut nexus: iroha_config::parameters::actual::Nexus,
) {
    // This fixture installs a complete physical catalog, not a process-local
    // override. Its World projection must retain the same dataspace baseline.
    nexus.configured_dataspace_catalog = nexus.dataspace_catalog.clone();
    nexus.lane_config = RuntimeLaneConfig::from_catalog(&nexus.lane_catalog);
    let previous_nexus = state.nexus_snapshot();
    let previous_lane_config = previous_nexus.lane_config;
    let previous_incarnations = state.lane_incarnations_snapshot();
    let previous_activations = state.lane_incarnation_activation_heights_snapshot();
    let previous_lineage = state.lane_incarnation_lineage_snapshot();
    let mut incarnations = derive_static_lane_incarnations(&nexus.lane_catalog);
    let mut activation_heights = nexus
        .lane_catalog
        .lanes()
        .iter()
        .map(|lane| (lane.id, 0))
        .collect::<BTreeMap<_, _>>();
    // Genesis identities include the entire initial catalog. Extending a
    // fixture later must retain an unchanged lane's admitted physical identity,
    // just as a real lifecycle transition does, instead of re-running genesis.
    let retained_lanes = nexus
        .lane_catalog
        .lanes()
        .iter()
        .filter(|lane| {
            previous_nexus.lane_catalog.lanes().iter().any(|previous| {
                previous.id == lane.id
                    && merge_lane_config_hash(previous) == merge_lane_config_hash(lane)
            })
        })
        .map(|lane| lane.id)
        .collect::<BTreeSet<_>>();
    for lane_id in &retained_lanes {
        incarnations.insert(*lane_id, previous_incarnations[lane_id]);
        activation_heights.insert(*lane_id, previous_activations[lane_id]);
    }
    validate_lane_incarnation_map(&nexus.lane_catalog, &incarnations)
        .expect("test Nexus incarnation map is valid");
    validate_lane_incarnation_activation_heights(&nexus.lane_catalog, &activation_heights)
        .expect("test Nexus activation-height map is valid");
    let lineage = incarnations
        .iter()
        .map(|(&lane_id, &incarnation)| {
            let entry = if retained_lanes.contains(&lane_id) {
                previous_lineage[&lane_id]
            } else {
                LaneIncarnationLineage {
                    generation: 0,
                    incarnation,
                    activation_height: activation_heights[&lane_id],
                }
            };
            (lane_id, entry)
        })
        .collect();
    state
        .kura
        .bind_lane_storage_network(state.network_id)
        .expect("exact fixture network");
    if let Some(baseline) = state.kura.configured_lane_catalog_baseline().unwrap() {
        let configured = configured_primary_replay_geometry(&nexus.configured_lane_catalog)
            .expect("fixture retains the exact configured primary geometry");
        state
            .kura
            .establish_or_verify_configured_primary_geometry_anchor(
                configured.lane_config.primary(),
                configured.primary_incarnation,
                baseline,
            )
            .expect("retain the fixture's actual initial primary anchor");
    }
    let replaced = previous_incarnations
        .iter()
        .filter_map(|(lane, previous)| {
            incarnations
                .get(lane)
                .filter(|current| *current != previous)
                .map(|_| *lane)
        })
        .collect();
    state
        .apply_lane_geometry_updates(
            &previous_lane_config,
            &nexus.lane_config,
            &previous_incarnations,
            &incarnations,
            &previous_activations,
            &activation_heights,
            &previous_lineage,
            &lineage,
            &replaced,
            u64::try_from(state.block_hashes.view().len()).expect("fixture height"),
            &mut LaneLifecycleReleases::new(state),
        )
        .expect("journal the exact structural fixture reference transition");
    state
        .mark_lane_geometry_catalog_published(
            &nexus.lane_config,
            &incarnations,
            &activation_heights,
            &lineage,
            None,
            &mut LaneLifecycleReleases::new(state),
        )
        .unwrap_or_else(|failure| {
            panic!(
                "publish exact fixture reference frontier: {}",
                failure.error
            )
        });
    // Rebind the original immutable source set; catalog projection never invents
    // a manifest or reopens the removed source files.
    let manifests = state
        .lane_manifests
        .read()
        .rebind(&nexus.lane_catalog, &nexus.governance);
    manifests
        .validate_materialized_authority_for_catalog(&nexus.lane_catalog, &nexus.governance)
        .expect("fixture geometry retains its materialized frozen authority");
    state.install_lane_manifests_for_testing(&Arc::new(manifests));
    state
        .install_canonical_runtime_projection(
            &nexus,
            &lineage,
            &state.autoscale_sample_history_snapshot(),
        )
        .expect("install complete pre-genesis runtime fixture");
    *state.nexus.write() = nexus;
    state.replace_active_lane_markers_for_tests();
}
