state_test! { sync account_scope_hierarchy_tracks_dataspaces_and_domains
    let state = blank_state();
    let block = new_dummy_block_with_payload(|_| {});
    let mut state_block = state.block(block.as_ref().header());
    let mut stx = state_block.transaction();
    let retail_dataspace = DataSpaceId::new(17);
    let_row! { dataspace_catalog = iroha_data_model::nexus::DataSpaceCatalog::new(vec![ iroha_data_model::nexus::DataSpaceMetadata { id: DataSpaceId::UNIVERSAL, alias: "universal".to_string(), description: None, fault_tolerance: 1, }, iroha_data_model::nexus::DataSpaceMetadata { id: retail_dataspace, alias: "retail".to_string(), description: None, fault_tolerance: 1, }, ]) .expect("dataspace catalog") };
    stx.nexus.dataspace_catalog = dataspace_catalog.clone();
    stx.world.dataspace_catalog = dataspace_catalog;
    let authority = AccountId::new(crate::state::checked_keypair().public_key().clone());
    let account_id = AccountId::new(crate::state::checked_keypair().public_key().clone());
    Register::account(Account::new(authority.clone()))
        .execute(&authority, &mut stx)
        .expect("register authority");
    Register::account(Account::new(account_id.clone()))
        .execute(&authority, &mut stx)
        .expect("register account");
    let universal_domain: DomainId = DomainId::try_new("treasury", "universal").expect("domain");
    let retail_domain: DomainId = DomainId::try_new("treasury", "retail").expect("domain");
    let_row! { universal_alias = iroha_data_model::account::rekey::AccountAlias::new( "rootdesk".parse().expect("label"), Some(iroha_data_model::account::rekey::AccountAliasDomain::new( universal_domain.name().clone(), )), DataSpaceId::UNIVERSAL, ) };
    let_row! { retail_alias = iroha_data_model::account::rekey::AccountAlias::new( "retaildesk".parse().expect("label"), Some(iroha_data_model::account::rekey::AccountAliasDomain::new( retail_domain.name().clone(), )), retail_dataspace, ) };
    stx.world
        .account_mut(&account_id)
        .expect("account exists")
        .set_label(Some(universal_alias.clone()));
    stx.world
        .insert_account_alias_binding(universal_alias.clone(), account_id.clone());
    stx.world
        .insert_account_alias_binding(retail_alias, account_id.clone());
    let_row! { hierarchy = stx .world .account_scope_hierarchy(&account_id) .expect("account hierarchy") };
    assert_eq!(
        hierarchy.get(&DataSpaceId::UNIVERSAL),
        Some(&BTreeSet::from([universal_domain.clone()])),
        "universal dataspace should expose the bound universal domain",
    );
    assert_eq!(
        hierarchy.get(&retail_dataspace),
        Some(&BTreeSet::from([retail_domain.clone()])),
        "retail dataspace should expose the bound retail domain",
    );
    assert_eq!(
        stx.world
            .account_dataspaces(&account_id)
            .expect("account dataspaces"),
        BTreeSet::from([DataSpaceId::UNIVERSAL, retail_dataspace]),
        "accounts should expose the universal dataspace plus extra bindings",
    );
    assert_eq!(
        stx.world
            .account_domains(&account_id)
            .expect("account domains"),
        BTreeSet::from([universal_domain, retail_domain]),
        "domains should flatten across all bound dataspaces",
    );
}
state_test! { sync account_scope_directory_tracks_alias_bind_and_unbind
    let state = blank_state();
    let block = new_dummy_block_with_payload(|_| {});
    let mut state_block = state.block(block.as_ref().header());
    let mut stx = state_block.transaction();
    let retail_dataspace = DataSpaceId::new(17);
    let_row! { dataspace_catalog = iroha_data_model::nexus::DataSpaceCatalog::new(vec![ iroha_data_model::nexus::DataSpaceMetadata::default(), iroha_data_model::nexus::DataSpaceMetadata { id: retail_dataspace, alias: "retail".to_string(), description: None, fault_tolerance: 1, }, ]) .expect("dataspace catalog") };
    stx.nexus.dataspace_catalog = dataspace_catalog.clone();
    stx.world.dataspace_catalog = dataspace_catalog;
    let authority = AccountId::new(crate::state::checked_keypair().public_key().clone());
    let account_id = AccountId::new(crate::state::checked_keypair().public_key().clone());
    Register::account(Account::new(authority.clone()))
        .execute(&authority, &mut stx)
        .expect("register authority");
    Register::account(Account::new(account_id.clone()))
        .execute(&authority, &mut stx)
        .expect("register account");
    let_row! { retail_alias = iroha_data_model::account::rekey::AccountAlias::new( "retaildesk".parse().expect("label"), Some(iroha_data_model::account::rekey::AccountAliasDomain::new( "treasury".parse::<Name>().expect("domain name"), )), retail_dataspace, ) };
    let retail_domain = DomainId::try_new("treasury", "retail").expect("retail domain id");
    let scope_key = stx.world.account_scope_domain_key(&retail_domain).expect("scope key");
    assert!(stx.world.account_scope_account_counts.get(&scope_key).is_none());
    let_row! { initial_scopes = stx .world .account_scope_entry(&account_id) .expect("materialized account should have an account scope entry") .iter() .map(|(dataspace_id, domains)| (*dataspace_id, domains.clone())) .collect::<BTreeMap<_, _>>() };
    assert_eq!(
        initial_scopes,
        BTreeMap::from([(DataSpaceId::UNIVERSAL, BTreeSet::new())]),
        "materialized accounts should start in the universal dataspace only",
    );
    assert!(
        stx.world
            .account_subjects_in_domain(&retail_domain)
            .is_empty(),
        "reverse account-scope index should start empty for the retail domain",
    );
    stx.world
        .insert_account_alias_binding(retail_alias.clone(), account_id.clone());
    stx.world.insert_account_alias_binding(retail_alias.clone(), account_id.clone());
    assert_eq!(stx.world.account_scope_account_counts.get(&scope_key), Some(&1),
        "replacing the same alias must not count the account twice");
    let_row! { bound_scopes = stx .world .account_scope_entry(&account_id) .expect("bound account scope entry") .iter() .map(|(dataspace_id, domains)| (*dataspace_id, domains.clone())) .collect::<BTreeMap<_, _>>() };
    assert_eq!(
        bound_scopes,
        BTreeMap::from([
            (DataSpaceId::UNIVERSAL, BTreeSet::new()),
            (
                retail_dataspace,
                BTreeSet::from([iroha_data_model::account::rekey::AccountAliasDomain::new(
                    "treasury".parse::<Name>().expect("domain name"),
                )]),
            ),
        ]),
        "alias binds should immediately refresh the account scope directory",
    );
    assert_eq!(
        stx.world.account_subjects_in_domain(&retail_domain),
        vec![account_id.clone()],
        "alias binds should update the reverse account-scope index",
    );
    stx.world.remove_account_alias_binding(&retail_alias);
    assert!(stx.world.account_scope_account_counts.get(&scope_key).is_none(),
        "removing the last account membership removes the scope count");
    let_row! { unbound_scopes = stx .world .account_scope_entry(&account_id) .expect("account scope entry should remain after unbind") .iter() .map(|(dataspace_id, domains)| (*dataspace_id, domains.clone())) .collect::<BTreeMap<_, _>>() };
    assert_eq!(
        unbound_scopes,
        BTreeMap::from([(DataSpaceId::UNIVERSAL, BTreeSet::new())]),
        "alias unbinds should remove the extra dataspace from the account scope directory",
    );
    assert!(
        stx.world
            .account_subjects_in_domain(&retail_domain)
            .is_empty(),
        "alias unbinds should update the reverse account-scope index",
    );
}
state_test! { sync rwas_in_domain_iter_uses_domain_range
    let owner = AccountId::new(crate::state::checked_keypair().public_key().clone());
    let alpha_domain = DomainId::try_new("alpha", "universal").expect("alpha domain");
    let beta_domain = DomainId::try_new("beta", "universal").expect("beta domain");
    let alpha_first_id = RwaId::generated(alpha_domain.clone(), Hash::new("alpha-1"));
    let alpha_second_id = RwaId::generated(alpha_domain.clone(), Hash::new("alpha-2"));
    let beta_id = RwaId::generated(beta_domain, Hash::new("beta-1"));
    let_row! { lot = |id: RwaId| { Rwa::new( id, 1_u32, NumericSpec::integer(), "certificate".to_owned(), None, Metadata::default(), Vec::new(), RwaControlPolicy { controller_accounts: Vec::new(), controller_roles: Vec::new(), freeze_enabled: false, hold_enabled: false, force_transfer_enabled: false, redeem_enabled: false, }, owner.clone(), ) .into_key_value() } };
    let mut world = World::default();
    let (id, value) = lot(alpha_first_id.clone());
    world.rwas.insert(id, value);
    let (id, value) = lot(beta_id);
    world.rwas.insert(id, value);
    let (id, value) = lot(alpha_second_id.clone());
    world.rwas.insert(id, value);
    let_row! { alpha_ids = world .view() .rwas_in_domain_iter(&alpha_domain) .map(|entry| entry.id().clone()) .collect::<Vec<_>>() };
    let mut expected = vec![alpha_first_id, alpha_second_id];
    expected.sort();
    assert_eq!(
        alpha_ids, expected,
        "domain range should only return RWAs in the requested domain",
    );
}
state_test! { sync rwas_in_account_iter_uses_owner_index
    let owner = AccountId::new(crate::state::checked_keypair().public_key().clone());
    let other_owner = AccountId::new(crate::state::checked_keypair().public_key().clone());
    let domain = DomainId::try_new("vault", "universal").expect("domain");
    let owner_first_id = RwaId::generated(domain.clone(), Hash::new("owner-1"));
    let owner_second_id = RwaId::generated(domain.clone(), Hash::new("owner-2"));
    let other_id = RwaId::generated(domain, Hash::new("other-1"));
    let_row! { lot = |id: RwaId, owner: AccountId| { Rwa::new( id, 1_u32, NumericSpec::integer(), "certificate".to_owned(), None, Metadata::default(), Vec::new(), RwaControlPolicy::default(), owner, ) .into_key_value() } };
    let mut world = World::default();
    let (id, value) = lot(owner_first_id.clone(), owner.clone());
    world.rwas.insert(id, value);
    let (id, value) = lot(other_id, other_owner);
    world.rwas.insert(id, value);
    let (id, value) = lot(owner_second_id.clone(), owner.clone());
    world.rwas.insert(id, value);
    world.rebuild_rwa_indexes();
    let_row! { owner_ids = world .view() .rwas_in_account_iter(&owner) .map(|entry| entry.id().clone()) .collect::<Vec<_>>() };
    let mut expected = vec![owner_first_id, owner_second_id];
    expected.sort();
    assert_eq!(
        owner_ids, expected,
        "owner index should only return RWA lots owned by the requested account",
    );
}
