state_test! { sync committed_replay_skips_failed_external_after_sealed_commitment
    let (authority, keypair) = gen_account_in("wonderland");
    let domain = Domain::new(sample_domain_id()).build(&authority);
    let account = Account::new(authority.clone()).build(&authority);
    let_row! { state = State::new_for_testing( World::with([domain], [account], []), Kura::blank_kura_for_testing(), LiveQueryStore::start_test(), ) };
    let network_id = *state.network_id_ref();
    let_row! { inner_tx = TransactionBuilder::new( network_id, authority.clone(), iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None), ) .sign(keypair.private_key()) };
    let_row! { commitment = iroha_data_model::transaction::signed::compute_sealed_transaction_commitment( &network_id, &inner_tx, [0x58; 32], 5, ) };
    let_row! { sealed_payload = iroha_data_model::transaction::signed::SealedTransactionCommitmentPayload { network_id, authority: authority.clone(), commitment, reveal_after_height: 2, reveal_deadline_height: 5, nonce: None, } };
    let_row! { sealed_entrypoint = TransactionEntrypoint::SealedCommitment( iroha_data_model::transaction::signed::SignedSealedTransactionCommitment::sign( sealed_payload, keypair.private_key(), ), ) };
    let sealed_hash = sealed_entrypoint.hash();
    let rejected_domain_id = DomainId::try_new("rejectedreplay", "universal").expect("domain id");
    let_row! { rejected_tx = TransactionBuilder::new( network_id, authority.clone(), iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None), ) .with_instructions([Register::domain(Domain::new(rejected_domain_id.clone()))]) .sign(keypair.private_key()) };
    let rejected_hash = rejected_tx.hash_as_entrypoint();
    let header = BlockHeader::new(nonzero!(1_u64), None, None, 0, 0);
    let_row! { signature = iroha_data_model::block::BlockSignature::new( 0, iroha_crypto::SignatureOf::try_from_hash(keypair.private_key(), header.hash()) .expect("test block signing should succeed"), ) };
    let mut block = SignedBlock::presigned(signature, header, vec![rejected_tx.clone()]);
    block.set_external_entrypoints(vec![
        sealed_entrypoint,
        TransactionEntrypoint::External(rejected_tx),
    ]);
    { let outputs = crate::execution_output_test_support::structural_network_outputs(&block, &[sealed_hash, rejected_hash], vec![
                TransactionResultInner::Ok(DataTriggerSequence::default()),
                TransactionResultInner::Err(
                    iroha_data_model::transaction::error::TransactionRejectionReason::Validation(
                        iroha_data_model::ValidationFail::NotPermitted(
                            "failed replay fixture".to_owned(),
                        ),
                    ),
                ),
            ]);
let fragments = u64::try_from(outputs.iter().filter(|row| row.result().is_ok()).count()).unwrap();
block.set_execution_outputs(outputs, fragments, std::collections::BTreeMap::default(),
Vec::new(),
iroha_data_model::nexus::AxtPolicySnapshot::default(),
std::collections::BTreeSet::default(),
&crate::execution_output_test_support::structural_output_limits()) }
        .expect("test block entrypoint hashes should match payload");
    let_row! { committed = crate::block::ValidBlock::new_unverified_for_tests(block) .commit_unchecked(crate::block::reserve_block_for_tests()) .unpack(|_| {}) };
    let state_block = state.block(committed.as_ref().header());
    assert!(state_block.verify_execution_output_seal(committed.as_ref()).is_err(),
        "a fabricated committed rejection must not bypass actual source execution");
    assert_eq!(state.committed_height(), 0, "rejected replay grants no State publication");
    let view = state.view();
    assert!(
        view.world().domains().get(&rejected_domain_id).is_none(),
        "failed external transaction after sealed entrypoint must not be replay-applied"
    );
}

