state_test! { sync pipeline_snapshot_reflects_latest_pipeline_config
    let mut state = blank_test_state();
    let committed_minimum = state.pipeline_snapshot().query_stored_min_gas_units;
    let mut updated = state.pipeline_snapshot();
    updated.query_default_cursor_mode = iroha_config::parameters::actual::QueryCursorMode::Stored;
    updated.query_stored_min_gas_units = updated.query_stored_min_gas_units.saturating_add(77);
    state.set_pipeline(updated.clone());
    let snapshot = state.pipeline_snapshot();
    assert_eq!(
        snapshot.query_default_cursor_mode,
        iroha_config::parameters::actual::QueryCursorMode::Stored
    );
    assert_eq!(state.installed_pipeline().query_stored_min_gas_units, updated.query_stored_min_gas_units);
    assert_eq!(snapshot.query_stored_min_gas_units, committed_minimum,
        "a local setting cannot replace consensus query validity");
    let mut policy = crate::pipeline_validity_policy::PipelineValidityPolicyV1::protocol_default();
    policy.query_stored_min_gas_units = updated.query_stored_min_gas_units;
    {
        let mut parameters = state.world.parameters.block();
        parameters.get_mut().set_parameter(Parameter::Custom(policy.clone().into_custom_parameter())).unwrap();
        parameters.commit();
    }
    assert_eq!(state.pipeline_snapshot().query_stored_min_gas_units, updated.query_stored_min_gas_units);
    assert_eq!(state.view().pipeline().query_stored_min_gas_units, updated.query_stored_min_gas_units);
    updated.query_stored_min_gas_units += 1;
    state.set_pipeline(updated);
    let snapshot = state.pipeline_snapshot();
    assert_eq!(snapshot.query_default_cursor_mode, iroha_config::parameters::actual::QueryCursorMode::Stored);
    assert_eq!(snapshot.query_stored_min_gas_units, policy.query_stored_min_gas_units,
        "pipeline reload preserves the latest committed query policy");
}
#[test]
fn executor_reconciliation_cannot_replace_signed_npos_parameters() {
    let installed = SumeragiNposParameters {
        evidence_horizon_blocks: 80,
        slashing_delay_blocks: 40,
        ..SumeragiNposParameters::default()
    };
    let attacker_value = SumeragiNposParameters {
        evidence_horizon_blocks: 1,
        slashing_delay_blocks: 1,
        ..installed.clone()
    };
    let state = blank_test_state();
    {
        let mut parameters = state.world.parameters.block();
        parameters
            .set_parameter(iroha_data_model::parameter::Parameter::Custom(
                installed.clone().into_custom_parameter(),
            ))
            .expect("valid fixture parameters");
        parameters.commit();
    }
    let mut attacker_model = ExecutorDataModel::default();
    attacker_model.parameters.insert(
        SumeragiNposParameters::parameter_id(),
        attacker_value.into_custom_parameter(),
    );

    let signed_payload = empty_signed_block_after(None, 1);
    let mut block = state.block(signed_payload.header());
    {
        let mut transaction = block.transaction();
        transaction.world.apply_executor_data_model(attacker_model);
        assert_eq!(
            transaction
                .world
                .sumeragi_npos_parameters()
                .expect("original policy decoder completes")
                .expect("signed NPoS parameters remain installed"),
            installed
        );
        assert!(
            transaction
                .world
                .executor_data_model
                .get()
                .parameters()
                .get(&SumeragiNposParameters::parameter_id())
                .is_none(),
            "executor-owned schemas must not acquire the consensus-owned parameter"
        );
    }
}
state_test! { sync executor_data_model_reconciliation_purges_undeclared_permissions_statefully
    let_row! { retained: Permission = iroha_executor_data_model::permission::parameter::CanSetParameters.into() };
    let retired = Permission::new("RetiredPermission".to_owned(), Json::new(()));
    let role_id: RoleId = "executor_reconciliation_role".parse().expect("role id");
    let_row! { role = Role { id: role_id.clone(), permissions: BTreeSet::from([retained.clone(), retired.clone()]), permission_epochs: BTreeMap::from([(retained.clone(), 4), (retired.clone(), 5)]), } };
    let_row! { mut world = World::with_assets_and_roles( [], [Account::new(ALICE_ID.clone()).build(&ALICE_ID)], [], [], [], [role], ) };
    world.account_permissions.insert(
        ALICE_ID.clone(),
        BTreeSet::from([retained.clone(), retired.clone()]),
    );
    let_row! { data_model = ExecutorDataModel::new( BTreeMap::new(), BTreeSet::new(), BTreeSet::from([retained.name().to_owned()]), Json::new(()), ) };
    let_row! { state = State::new_for_testing( world, Kura::blank_kura_for_testing(), LiveQueryStore::start_test(), ) };
    let mut block = state.block(BlockHeader::new(nonzero!(2_u64), None, None, 0, 0));
    let mut transaction = block.transaction();
    transaction
        .world
        .apply_executor_data_model(data_model.clone());
    let_row! { account_permissions = transaction .world .account_permissions .get(&ALICE_ID) .expect("retained account permission entry") };
    assert_eq!(account_permissions, &BTreeSet::from([retained.clone()]));
    let_row! { role = transaction .world .roles .get(&role_id) .expect("reconciled role") };
    assert_eq!(
        role.permissions().cloned().collect::<BTreeSet<_>>(),
        BTreeSet::from([retained.clone()]),
    );
    assert_eq!(role.permission_epochs().get(&retained), Some(&4));
    assert!(!role.permission_epochs().contains_key(&retired));
    assert_eq!(
        transaction.world.executor_data_model.get(),
        &data_model,
        "the permission purge and model update must be one stateful operation",
    );
}
