state_test! { sync autoscale_runtime_lane_bounds_reject_empty_inverted_or_excessive_max
    let_row! { mut autoscale = iroha_config::parameters::actual::Autoscale { min_lane_id: nonzero!(4_u32), max_lane_id_exclusive: nonzero!(3_u32), ..Default::default() } };
    let_row! { err = ensure_autoscale_runtime_lane_bounds(&autoscale) .expect_err("runtime autoscale bounds must reject inverted min/max") };
    assert!(matches!(
        err,
        LaneLifecycleError::AutoscaleInvalidLaneBounds {
            min_lane_id: 4,
            max_lane_id_exclusive: 3
        }
    ));
    autoscale.min_lane_id = nonzero!(4_u32);
    autoscale.max_lane_id_exclusive = nonzero!(4_u32);
    let_row! { err = ensure_autoscale_runtime_lane_bounds(&autoscale) .expect_err("runtime autoscale bounds must reject empty elastic ranges") };
    assert!(matches!(
        err,
        LaneLifecycleError::AutoscaleInvalidLaneBounds {
            min_lane_id: 4,
            max_lane_id_exclusive: 4
        }
    ));
    let cap = iroha_config::parameters::defaults::nexus::autoscale::MAX_LANE_ID_EXCLUSIVE;
    autoscale.min_lane_id = nonzero!(1_u32);
    autoscale.max_lane_id_exclusive = NonZeroU32::new(cap.saturating_add(1)).expect("cap + 1 remains nonzero");
    let_row! { err = ensure_autoscale_runtime_lane_bounds(&autoscale) .expect_err("runtime autoscale bounds must reject values above the safety cap") };
    assert!(matches!(
        err,
        LaneLifecycleError::AutoscaleMaxLaneIdExclusiveExceedsCap {
            max_lane_id_exclusive,
            cap: observed_cap,
        } if max_lane_id_exclusive == cap.saturating_add(1) && observed_cap == cap
    ));
}
state_test! { sync autoscale_runtime_elastic_range_rejects_manual_or_malformed_in_range
    let_row! { manual_in_range = autoscale_transition_test_nexus( vec![ LaneConfig::default(), LaneConfig { id: LaneId::new(1), alias: "manual-in-elastic-range".to_owned(), ..LaneConfig::default() }, ], 1, 3, 100, ) };
    let_row! { err = ensure_autoscale_runtime_elastic_range(&manual_in_range) .expect_err("runtime autoscale precheck must reject manual lanes in elastic range") };
    assert!(matches!(
        err,
        LaneLifecycleError::ReservedAutoscaleElasticLaneId {
            lane,
            min_lane_id: 1,
            max_lane_id_exclusive: 3
        } if lane == LaneId::new(1)
    ));
    let mut malformed = autoscale_elastic_lane_config(LaneId::new(1), DataSpaceId::UNIVERSAL, 2);
    malformed.alias = "not-elastic-lane-1".to_owned();
    let_row! { malformed_in_range = autoscale_transition_test_nexus(vec![LaneConfig::default(), malformed], 1, 3, 100) };
    let_row! { err = ensure_autoscale_runtime_elastic_range(&malformed_in_range) .expect_err("runtime autoscale precheck must reject malformed managed lanes in range") };
    assert!(matches!(
        err,
        LaneLifecycleError::InvalidAutoscaleManagedLane { lane, reason }
            if lane == LaneId::new(1) && reason == "alias must match elastic-lane-{id}"
    ));
    let_row! { out_of_range_managed = autoscale_transition_test_nexus( vec![ LaneConfig::default(), autoscale_elastic_lane_config(LaneId::new(3), DataSpaceId::UNIVERSAL, 2), ], 1, 3, 100, ) };
    let_row! { err = ensure_autoscale_runtime_elastic_range(&out_of_range_managed) .expect_err("runtime autoscale precheck must reject owned lanes outside the range") };
    assert!(matches!(
        err,
        LaneLifecycleError::AutoscaleManagedLaneOutOfBounds {
            lane,
            min_lane_id: 1,
            max_lane_id_exclusive: 3
        } if lane == LaneId::new(3)
    ));
    let_row! { mut marker_only = LaneConfig { id: LaneId::new(8), alias: "marked-manual-sidecar".to_owned(), ..LaneConfig::default() } };
    marker_only
        .metadata
        .insert(AUTOSCALE_META_CREATED_HEIGHT.to_owned(), "42".to_owned());
    let_row! { marker_only_out_of_range = autoscale_transition_test_nexus(vec![LaneConfig::default(), marker_only], 1, 3, 100) };
    let_row! { err = ensure_autoscale_runtime_elastic_range(&marker_only_out_of_range) .expect_err("runtime autoscale precheck must reject marker-only manual lanes") };
    assert!(matches!(
        err,
        LaneLifecycleError::ReservedAutoscaleManagedLane(id) if id == LaneId::new(8)
    ));
}
state_test! { sync autoscale_runtime_elastic_range_rejects_profile_drift_and_restricted_base
    let_row! { mut base_lane = LaneConfig { lane_type: Some("regulated-public".to_owned()), settlement: Some("settlement-v3".to_owned()), ..LaneConfig::default() } };
    base_lane
        .metadata
        .insert("security.profile".to_owned(), "strict".to_owned());
    let_row! { mut valid_lane = autoscale_elastic_lane_config_from_base(LaneId::new(1), &base_lane, 2) .expect("public base profile should produce a managed lane") };
    attach_synthetic_autoscale_committee_for_test(&mut valid_lane);
    let mut drifted_lane = valid_lane.clone();
    drifted_lane.storage = LaneStorageProfile::SplitReplica;
    let drifted = autoscale_transition_test_nexus(vec![base_lane.clone(), drifted_lane], 1, 3, 100);
    let_row! { err = ensure_autoscale_runtime_elastic_range(&drifted) .expect_err("runtime autoscale precheck must reject inherited profile drift") };
    assert!(matches!(
        err,
        LaneLifecycleError::InvalidAutoscaleManagedLane { lane, reason }
            if lane == LaneId::new(1) && reason == AUTOSCALE_PROFILE_DRIFT_REASON
    ));
    let restricted_dataspace = DataSpaceId::new(1);
    let mut restricted_base = base_lane;
    restricted_base.dataspace_id = restricted_dataspace;
    restricted_base.visibility = LaneVisibility::Restricted;
    let mut restricted = autoscale_transition_test_nexus(vec![restricted_base], 1, 3, 100);
    restricted.dataspace_catalog = dataspace_catalog_with_extra(restricted_dataspace);
    restricted.configured_dataspace_catalog = restricted.dataspace_catalog.clone();
    restricted.configured_lane_catalog = restricted.lane_catalog.clone();
    restricted.routing_policy.default_dataspace = restricted_dataspace;
    let mut prospective_lane = valid_lane;
    prospective_lane.dataspace_id = restricted_dataspace;
    // A canonical catalog cannot mix a restricted base and public managed lane
    // in one dataspace. Test the same profile predicate before adding the lane.
    let_row! { err = ensure_autoscale_managed_lane_inherits_default_profile(&prospective_lane, &restricted)
        .expect_err("autoscale profile precheck must reject a restricted routing base") };
    assert!(matches!(
        err,
        LaneLifecycleError::InvalidAutoscaleManagedLane { lane, reason }
            if lane == LaneId::new(1) && reason == AUTOSCALE_RESTRICTED_BASE_REASON
    ));
}
