fn manual_lane_lifecycle_payload() -> iroha_data_model::nexus::LaneLifecycleParameterV1 {
    let expected_catalog = LaneCatalog::default();
    let incarnations = derive_static_lane_incarnations(&expected_catalog);
    let_row! { incarnations = iroha_data_model::nexus::LaneLifecycleParameterV1::canonical_incarnations( &expected_catalog, &incarnations, ) .expect("default lifecycle incarnation set is canonical") };
    iroha_data_model::nexus::LaneLifecycleParameterV1::new(
        &expected_catalog,
        &incarnations,
        iroha_data_model::nexus::LaneLifecyclePlan {
            additions: vec![LaneConfig {
                id: LaneId::new(1),
                alias: "manual-consensus-lane".to_owned(),
                ..LaneConfig::default()
            }],
            retire: Vec::new(),
        },
    )
    .expect("manual lifecycle payload is canonical")
}
fn manual_lane_lifecycle_test_state(world: World) -> State {
    let_row! { mut state = State::new_for_testing( world, Kura::blank_kura_for_testing(), LiveQueryStore::start_test(), ) };
    let_row! { mut nexus = iroha_config::parameters::actual::Nexus { ..Default::default() } };
    nexus.fees.base_fee = Quantity::zero();
    nexus.fees.per_byte_fee = Quantity::zero();
    nexus.fees.per_instruction_fee = Quantity::zero();
    nexus.fees.per_gas_unit_fee = Quantity::zero();
    state
        .set_nexus(nexus)
        .expect("install Nexus policy for manual lifecycle test");
    state
}

fn manual_lane_lifecycle_test_chain(
    world: World,
) -> crate::sumeragi::test_chain::CertifiedTestChain {
    let mut config = crate::sumeragi::test_chain::TestChainConfig::new(world, 0);
    let mut nexus = iroha_config::parameters::actual::Nexus::default();
    nexus.fees.base_fee = Quantity::zero();
    nexus.fees.per_byte_fee = Quantity::zero();
    nexus.fees.per_instruction_fee = Quantity::zero();
    nexus.fees.per_gas_unit_fee = Quantity::zero();
    config.nexus = Some(nexus);
    crate::sumeragi::test_chain::CertifiedTestChain::start(config)
        .expect("original native lifecycle predecessor")
}

fn commit_manual_lane_lifecycle(
    chain: &mut crate::sumeragi::test_chain::CertifiedTestChain,
    signer: &KeyPair,
) {
    let transaction = chain.sign(
        signer,
        [iroha_data_model::isi::SetParameter::new(Parameter::Custom(
            manual_lane_lifecycle_payload().into_custom_parameter(),
        ))
        .into()],
        1,
    );
    assert_eq!(chain.commit(vec![transaction]), vec![true]);
}
state_test! { sync consensus_lane_lifecycle_replay_converges_on_fresh_state
    use iroha_executor_data_model::permission::parameter::CanSetParameters;
    let (authority, signer) = gen_account_in("universal");
    let_row! { replay_world = || { let domain = Domain::new(sample_domain_id()).build(&authority); let account = Account::new(authority.clone()).build(&authority); let mut world = World::with([domain], [account], []); world.account_permissions.insert( authority.clone(), BTreeSet::from([Permission::from(CanSetParameters)]), ); world } };
    let mut first_chain = manual_lane_lifecycle_test_chain(replay_world());
    let mut replay_chain = manual_lane_lifecycle_test_chain(replay_world());
    commit_manual_lane_lifecycle(&mut first_chain, &signer);
    commit_manual_lane_lifecycle(&mut replay_chain, &signer);
    let first = first_chain.state();
    let replay = replay_chain.state();
    assert_eq!(first.latest_block_hash_fast(), replay.latest_block_hash_fast());
    let first_nexus = first.nexus_snapshot();
    let replay_nexus = replay.nexus_snapshot();
    assert_eq!(first_nexus.lane_catalog, replay_nexus.lane_catalog);
    assert!(lane_config_entries_match(
        &first_nexus.lane_config,
        &replay_nexus.lane_config
    ));
    assert!(
        first_nexus
            .lane_catalog
            .lanes()
            .iter()
            .any(|lane| lane.id == LaneId::new(1)),
        "replayed signed lifecycle transaction must publish the new lane"
    );
    assert_eq!(
        first_nexus.autoscale.last_transition_height, 0,
        "manual transitions must not consume autoscale cooldown"
    );
    let (events_sender, _) = tokio::sync::broadcast::channel(8);
    let_row! { queue = crate::queue::Queue::from_config( iroha_config::parameters::actual::Queue::default(), events_sender, ) };
    assert!(queue.reconfigure_nexus_with_state_if_needed(&first_nexus, first, None,));
    assert!(
        !queue.reconfigure_nexus_with_state_if_needed(&first_nexus, first, None),
        "queue topology refresh must be idempotent after committed lifecycle publication"
    );
}
state_test! { sync consensus_lane_lifecycle_rejects_stale_catalog_without_overlay_mutation
    use crate::smartcontracts::Execute as _;
    let state = manual_lane_lifecycle_test_state(World::default());
    let header = BlockHeader::new(nonzero!(1_u64), None, None, 0, 0);
    let mut block = state.block(header);
    let mut transaction = block.transaction();
    let mut payload = manual_lane_lifecycle_payload();
    payload.expected_catalog_hash = Hash::new(b"stale-lane-catalog");
    let_row! { err = iroha_data_model::isi::SetParameter::new(Parameter::Custom( payload.into_custom_parameter(), )) .execute(&ALICE_ID, &mut transaction) .expect_err("stale catalog commitment must fail closed") };
    assert!(
        format!("{err:?}").contains("expected catalog hash"),
        "unexpected stale-catalog error: {err:?}"
    );
    drop(transaction);
    assert_eq!(block.nexus.lane_catalog, LaneCatalog::default());
    assert!(block.pending_autoscale_lifecycle.is_none());
}
state_test! { sync consensus_lane_lifecycle_rejects_second_transition_and_rolls_back_first
    use crate::smartcontracts::Execute as _;
    let state = manual_lane_lifecycle_test_state(World::default());
    let header = BlockHeader::new(nonzero!(1_u64), None, None, 0, 0);
    let mut block = state.block(header);
    let mut transaction = block.transaction();
    let_row! { instruction = || { iroha_data_model::isi::SetParameter::new(Parameter::Custom( manual_lane_lifecycle_payload().into_custom_parameter(), )) } };
    instruction()
        .execute(&ALICE_ID, &mut transaction)
        .expect("first transition may stage in the transaction overlay");
    let_row! { err = instruction() .execute(&ALICE_ID, &mut transaction) .expect_err("a second transition in the same transaction must be rejected") };
    assert!(
        format!("{err:?}").contains("already staged"),
        "unexpected duplicate-transition error: {err:?}"
    );
    drop(transaction);
    assert_eq!(block.nexus.lane_catalog, LaneCatalog::default());
    assert!(block.pending_autoscale_lifecycle.is_none());
}
state_test! { sync normal_validation_requires_can_set_parameters_for_lane_lifecycle
    use iroha_executor_data_model::permission::parameter::CanSetParameters;
    let (authority, signer) = gen_account_in("universal");
    let domain = Domain::new(sample_domain_id()).build(&authority);
    let account = Account::new(authority.clone()).build(&authority);
    for authorized in [false, true] {
        let mut world = World::with([domain.clone()], [account.clone()], []);
        if authorized {
            world.account_permissions.insert(
                authority.clone(),
                BTreeSet::from([Permission::from(CanSetParameters)]),
            );
        }
        let chain = manual_lane_lifecycle_test_chain(world);
        let state = chain.state();
        let_row! { transaction = TransactionBuilder::new( *state.network_id_ref(), authority.clone(), iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None), ) .with_instructions([iroha_data_model::isi::SetParameter::new(Parameter::Custom( manual_lane_lifecycle_payload().into_custom_parameter(), ))]) .sign(signer.private_key()) };
        let accepted = AcceptedTransaction::new_unchecked(Cow::Owned(transaction));
        let parent = state.view().latest_block().expect("completed original State read").expect("original native predecessor");
        let_row! { unverified = BlockBuilder::new(vec![accepted]) .chain(0, Some(&parent)) .sign(signer.private_key()) .unpack(|_| {}) };
        let source: SignedBlock = unverified.into();
        let (mut state_block, guard) = crate::block::ValidBlock::start_component_execution(&source, state).expect("original recorder before execution");
        let_row! { committed = crate::block::ValidBlock::validate_unchecked(source, &mut state_block, guard) .unpack(|_| {}) .commit_unchecked(crate::block::reserve_block_for_tests()) .unpack(|_| {}) };
        let signed_payload = committed.into_shared();
        if authorized {
            assert!(
                signed_payload.output_error(0).is_none(),
                "CanSetParameters holder should pass lifecycle validation: {:?}",
                signed_payload.output_error(0)
            );
            assert!(state_block.pending_autoscale_lifecycle.is_some());
        } else {
            let_row! { rejection = format!( "{:?}", signed_payload .output_error(0) .expect("authority without CanSetParameters must be rejected") ) };
            assert!(
                rejection.contains("Can't set network parameters without CanSetParameters"),
                "unexpected permission rejection: {rejection}"
            );
            assert!(state_block.pending_autoscale_lifecycle.is_none());
        }
    }
}
