    let mut state = manual_lane_lifecycle_test_state(World::default());
    let lane = LaneConfig { id: LaneId::new(1), alias: "immutable-physical-lane".to_owned(), ..LaneConfig::default() };
    let catalog = LaneCatalog::new(nonzero!(2_u32), vec![LaneConfig::default(), lane.clone()]).unwrap();
    configure_pre_genesis_nexus_fixture(&mut state, iroha_config::parameters::actual::Nexus { lane_catalog: catalog.clone(), ..Default::default() });
    let incarnations = state.lane_incarnations_snapshot();
    let payload = iroha_data_model::nexus::LaneLifecycleParameterV1::new(&catalog,
        &iroha_data_model::nexus::LaneLifecycleParameterV1::canonical_incarnations(&catalog, &incarnations).unwrap(),
        iroha_data_model::nexus::LaneLifecyclePlan { additions: vec![lane], retire: vec![LaneId::new(1)] }).unwrap();
    let mut block = state.block(BlockHeader::new(nonzero!(1_u64), None, None, 0, 0));
    let mut transaction = block.transaction();
    transaction.stage_consensus_lane_lifecycle(&payload).expect_err("physical lane replacement is prohibited");
    assert_eq!(transaction.lane_incarnations, incarnations);
    drop(transaction);
    drop(block);
    assert_eq!(state.nexus_snapshot().lane_catalog, catalog);
    assert_eq!(state.lane_incarnations_snapshot(), incarnations);
