fn autoscale_drain_keypairs_for_test(count: usize) -> Vec<KeyPair> {
    if count == 4 {
        return synthetic_autoscale_committee_keypairs_for_test();
    }
    let_row! { mut keypairs = (0..count) .map(|index| { let seed = u8::try_from(index) .expect("drain committee test index must fit u8") .saturating_add(0x91); KeyPair::try_from_seed(vec![seed; 32], Algorithm::BlsNormal) .expect("deterministic lane drain BLS key") }) .collect::<Vec<_>>() };
    keypairs.sort_by(|left, right| {
        PeerId::new(left.public_key().clone()).cmp(&PeerId::new(right.public_key().clone()))
    });
    keypairs
}
#[test]
fn exact_autoscale_committee_needs_no_beacon_but_selection_and_duplicates_fail_closed() {
    let world = World::default();
    let nexus = iroha_config::parameters::actual::Nexus::default();
    let network_id = iroha_data_model::NetworkId::from_genesis_hash(
        HashOf::<BlockHeader>::from_untyped_unchecked(Hash::new(b"exact-autoscale-committee")),
    );
    let mut pool = autoscale_drain_keypairs_for_test(5)
        .into_iter()
        .map(|keypair| PeerId::new(keypair.public_key().clone()))
        .collect::<Vec<_>>();
    let derive = |pool: &[PeerId]| {
        State::autoscale_lane_committee_from_pool(
            &world.view(),
            &network_id,
            LaneId::new(1),
            DataSpaceId::UNIVERSAL,
            &nexus,
            pool,
            2,
        )
    };
    assert!(
        derive(&pool).is_empty(),
        "choosing members requires verified entropy"
    );
    pool.pop();
    let mut expected = pool.clone();
    expected.sort();
    assert_eq!(derive(&pool), expected);
    pool.reverse();
    assert_eq!(
        derive(&pool),
        expected,
        "exact membership is canonically ordered"
    );
    pool[0] = pool[1].clone();
    assert!(
        derive(&pool).is_empty(),
        "a duplicate cannot pad the committee"
    );
}
