#[cfg(feature = "sm")]
state_test! { sync set_crypto_updates_sm2_distid_default
    struct DistidGuard(String);
    impl Drop for DistidGuard {
        fn drop(&mut self) {
            Sm2PublicKey::set_default_distid(self.0.clone())
                .expect("sm2_distid_default must be valid");
        }
    }
    let original = Sm2PublicKey::default_distid();
    let _guard = DistidGuard(original.clone());
    let kura = Kura::blank_kura_for_testing();
    let query_handle = LiveQueryStore::start_test();
    let world = World::default();
    let state = State::new_for_testing(world, kura, query_handle);
    let mut crypto_cfg = (*state.crypto()).clone();
    crypto_cfg.sm2_distid_default = "runtime-override".to_owned();
    state.set_crypto(crypto_cfg.clone());
    assert_eq!(Sm2PublicKey::default_distid(), "runtime-override");
    crypto_cfg.sm2_distid_default = original;
    state.set_crypto(crypto_cfg);
}
state_test! { sync enforce_nexus_storage_budget_prunes_cold_snapshots
    let temp_dir = tempfile::tempdir().expect("temp dir");
    let store_root = temp_dir.path().join("kura");
    let cold_root = temp_dir.path().join("cold");
    let snapshot_dir = cold_root.join("00000000000000000001");
    std::fs::create_dir_all(&snapshot_dir).expect("create snapshot dir");
    std::fs::write(snapshot_dir.join("payload.norito"), vec![0u8; 50]).expect("write cold payload");
    let newest_snapshot_dir = cold_root.join("00000000000000000002");
    std::fs::create_dir_all(&newest_snapshot_dir).expect("create newest snapshot dir");
    std::fs::write(newest_snapshot_dir.join("payload.norito"), vec![0u8; 50])
        .expect("write newest cold payload");
    let kura_cfg = strict_kura_config_for_testing(store_root);
    let (kura, _) = Kura::open_test_kura_with_configured_lane_config(&kura_cfg, &RuntimeLaneConfig::default()).expect("init kura");
    let query_handle = LiveQueryStore::start_test();
    let mut state = State::new_for_testing(World::default(), kura, query_handle);
    state
        .set_tiered_backend(&iroha_config::parameters::actual::TieredState {
            enabled: true,
            hot_retained_keys: 0,
            hot_retained_bytes: iroha_config::base::util::Bytes(0),
            hot_retained_grace_snapshots: 0,
            cold_store_root: Some(cold_root.clone()),
            da_store_root: None,
            max_snapshots: 0,
            max_cold_bytes: iroha_config::base::util::Bytes(0),
        })
        .expect("configure tiered state for storage budget test");
    let kura_used = state.kura.disk_usage_bytes().expect("measure kura bytes");
    let_row! { cold_used = { let backend = state.tiered_backend.lock(); backend .cold_store_bytes() .expect("measure cold store bytes") .unwrap_or(0) } };
    let total_used = kura_used.saturating_add(cold_used);
    let max_disk_usage = total_used.saturating_sub(1).max(1);
    let mut storage = iroha_config::parameters::actual::NexusStorage::default();
    storage.local_budget_bytes = Some(iroha_config::base::util::Bytes(max_disk_usage));
    storage.effective_local_budget_bytes = Some(iroha_config::base::util::Bytes(max_disk_usage));
    storage.budget_enforce_interval_blocks = 0;
    {
        let nexus = state.nexus.get_mut();
        nexus.storage = storage;
    }
    state.enforce_nexus_storage_budget(1);
    assert!(!snapshot_dir.exists(), "old cold snapshot should be evicted");
    assert!(newest_snapshot_dir.exists(), "the newest snapshot must remain available");
}
state_test! { sync enforce_nexus_storage_budget_respects_interval_blocks
    let temp_dir = tempfile::tempdir().expect("temp dir");
    let store_root = temp_dir.path().join("kura");
    let cold_root = temp_dir.path().join("cold");
    let snapshot_dir = cold_root.join("00000000000000000001");
    std::fs::create_dir_all(&snapshot_dir).expect("create snapshot dir");
    std::fs::write(snapshot_dir.join("payload.norito"), vec![0u8; 60]).expect("write cold payload");
    let newest_snapshot_dir = cold_root.join("00000000000000000002");
    std::fs::create_dir_all(&newest_snapshot_dir).expect("create newest snapshot dir");
    std::fs::write(newest_snapshot_dir.join("payload.norito"), vec![0u8; 60])
        .expect("write newest cold payload");
    let kura_cfg = strict_kura_config_for_testing(store_root);
    let (kura, _) = Kura::open_test_kura_with_configured_lane_config(&kura_cfg, &RuntimeLaneConfig::default()).expect("init kura");
    let query_handle = LiveQueryStore::start_test();
    let mut state = State::new_for_testing(World::default(), kura, query_handle);
    state
        .set_tiered_backend(&iroha_config::parameters::actual::TieredState {
            enabled: true,
            hot_retained_keys: 0,
            hot_retained_bytes: iroha_config::base::util::Bytes(0),
            hot_retained_grace_snapshots: 0,
            cold_store_root: Some(cold_root.clone()),
            da_store_root: None,
            max_snapshots: 0,
            max_cold_bytes: iroha_config::base::util::Bytes(0),
        })
        .expect("configure tiered state for storage budget test");
    let kura_used = state.kura.disk_usage_bytes().expect("measure kura bytes");
    let_row! { cold_used = { let backend = state.tiered_backend.lock(); backend .cold_store_bytes() .expect("measure cold store bytes") .unwrap_or(0) } };
    let total_used = kura_used.saturating_add(cold_used);
    let interval_blocks = 10;
    let mut storage = iroha_config::parameters::actual::NexusStorage::default();
    storage.local_budget_bytes = Some(iroha_config::base::util::Bytes(total_used));
    storage.effective_local_budget_bytes = Some(iroha_config::base::util::Bytes(total_used));
    storage.budget_enforce_interval_blocks = interval_blocks;
    {
        let nexus = state.nexus.get_mut();
        nexus.storage = storage;
    }
    state.enforce_nexus_storage_budget(1);
    assert!(
        snapshot_dir.exists(),
        "cold snapshot should remain under budget"
    );
    let max_disk_usage = total_used.saturating_sub(1).max(1);
    {
        let mut nexus = state.nexus.write();
        nexus.storage.effective_local_budget_bytes =
            Some(iroha_config::base::util::Bytes(max_disk_usage));
    }
    state.enforce_nexus_storage_budget(2);
    assert!(snapshot_dir.exists(), "cold eviction should be deferred");
    state.enforce_nexus_storage_budget(11);
    assert!(
        !snapshot_dir.exists(),
        "cold snapshot should be evicted once interval passes"
    );
    assert!(newest_snapshot_dir.exists(), "the newest snapshot must remain available");
}
state_test! { sync lane_topology_diff_marks_alias_changes_for_relabel
    let lane_count = nonzero!(1_u32);
    let_row! { initial_catalog = LaneCatalog::new( lane_count, vec![LaneConfig { alias: "Alpha Lane".to_string(), ..LaneConfig::default() }], ) .expect("initial catalog") };
    let_row! { updated_catalog = LaneCatalog::new( lane_count, vec![LaneConfig { alias: "Payments Lane".to_string(), ..LaneConfig::default() }], ) .expect("updated catalog") };
    let previous = RuntimeLaneConfig::from_catalog(&initial_catalog);
    let current = RuntimeLaneConfig::from_catalog(&updated_catalog);
    let diff = super::lane_topology_diff(&previous, &current, &BTreeSet::new());
    assert!(diff.added.is_empty(), "alias change should not add lanes");
    assert!(
        diff.retired.is_empty(),
        "alias change should not retire lanes"
    );
    assert_eq!(diff.relabelled.len(), 1, "lane should be relabelled");
    assert_eq!(diff.relabelled[0].0.alias, "Alpha Lane");
    assert_eq!(diff.relabelled[0].1.alias, "Payments Lane");
    assert!(
        super::lanes_requiring_state_reset(&previous, &current).is_empty(),
        "pure storage relabels must not reset lane runtime or economic state"
    );
}
state_test! { sync lane_topology_diff_tracks_forced_replacements_separately
    let lane_count = nonzero!(2_u32);
    let_row! { initial_catalog = LaneCatalog::new( lane_count, vec![ LaneConfig::default(), LaneConfig { id: LaneId::new(1), alias: "old-lane".to_string(), ..LaneConfig::default() }, ], ) .expect("initial catalog") };
    let_row! { updated_catalog = LaneCatalog::new( lane_count, vec![ LaneConfig::default(), LaneConfig { id: LaneId::new(1), alias: "fresh-lane".to_string(), ..LaneConfig::default() }, ], ) .expect("updated catalog") };
    let previous = RuntimeLaneConfig::from_catalog(&initial_catalog);
    let current = RuntimeLaneConfig::from_catalog(&updated_catalog);
    let replaced = BTreeSet::from([LaneId::new(1)]);
    let diff = super::lane_topology_diff(&previous, &current, &replaced);
    assert!(diff.added.is_empty(), "replacement should not add a lane");
    assert!(
        diff.retired.is_empty(),
        "replacement should not retire a lane"
    );
    assert_eq!(diff.replacements.len(), 1);
    assert_eq!(diff.replacements[0].0.alias, "old-lane");
    assert_eq!(diff.replacements[0].1.alias, "fresh-lane");
    assert!(
        diff.relabelled.is_empty(),
        "same-plan lane replacement must not relabel old storage into the fresh lane"
    );
}
