#[test]
fn apply_lane_lifecycle_internal_autoscale_rejects_runtime_max_lane_id_exclusive_above_safety_cap()
{
    let state = blank_test_state();
    enable_nexus_autoscale_for_testing(&state);
    {
        let cap = iroha_config::parameters::defaults::nexus::autoscale::MAX_LANE_ID_EXCLUSIVE;
        let mut nexus = state.nexus_snapshot();
        nexus.autoscale.max_lane_id_exclusive =
            NonZeroU32::new(cap.saturating_add(1)).expect("cap + 1 remains nonzero");
        state
            .install_canonical_runtime_projection(
                &nexus,
                &state.lane_incarnation_lineage_snapshot(),
                &state.autoscale_sample_history_snapshot(),
            )
            .expect("install explicitly corrupt runtime autoscale bound");
        *state.nexus.write() = nexus;
    }
    let lane = autoscale_elastic_lane_config(LaneId::new(1), DataSpaceId::UNIVERSAL, 2);
    let_row! { plan = iroha_data_model::nexus::LaneLifecyclePlan { additions: vec![lane], retire: Vec::new(), } };
    let_row! { err = state .apply_lane_lifecycle_with_options(&plan, false, true) .expect_err("internal autoscale lifecycle must reject corrupted max_lane_id_exclusive") };
    let cap = iroha_config::parameters::defaults::nexus::autoscale::MAX_LANE_ID_EXCLUSIVE;
    assert!(matches!(
        err,
        LaneLifecycleError::AutoscaleMaxLaneIdExclusiveExceedsCap {
            max_lane_id_exclusive,
            cap: observed_cap
        } if max_lane_id_exclusive == cap.saturating_add(1) && observed_cap == cap
    ));
    assert_eq!(
        state.nexus_snapshot().lane_catalog.lanes(),
        &[LaneConfig::default()],
        "rejected autoscale lifecycle must not mutate the active catalog"
    );
}
state_test! { sync apply_lane_lifecycle_internal_autoscale_rejects_managed_retire_outside_range
    let state = blank_test_state();
    enable_nexus_autoscale_for_testing(&state);
    let_row! { out_of_range_lane = autoscale_elastic_lane_config(LaneId::new(8), DataSpaceId::UNIVERSAL, 2) };
    {
        let mut nexus = state.nexus_snapshot();
        nexus.lane_catalog = LaneCatalog::new(
            nonzero!(9_u32),
            vec![LaneConfig::default(), out_of_range_lane.clone()],
        )
        .expect("corrupted runtime catalog with out-of-range managed lane");
        nexus.lane_config =
            iroha_config::parameters::actual::LaneConfig::from_catalog(&nexus.lane_catalog);
        install_existing_nexus_geometry_for_test(&state, nexus);
    }
    let_row! { plan = iroha_data_model::nexus::LaneLifecyclePlan { additions: Vec::new(), retire: vec![out_of_range_lane.id], } };
    let before_retirement = norito::json::to_value(&state).expect("original retirement State");
    let_row! { err = state .apply_lane_lifecycle_with_options(&plan, false, true) .expect_err("internal autoscale lifecycle must not retire out-of-range managed lanes") };
    assert!(matches!(
        err,
        LaneLifecycleError::UnsafeRetirement { lane, reason }
            if lane == plan.retire[0]
                && reason == "physical catalog retirement is unsupported; native lane closure retains its data"
    ));
    assert_eq!(
        norito::json::to_value(&state).expect("rejected physical retirement State"),
        before_retirement,
        "physical retirement must preserve all original State content"
    );
    assert!(
        state
            .nexus_snapshot()
            .lane_catalog
            .lanes()
            .iter()
            .any(|lane| lane.id == out_of_range_lane.id),
        "rejected retire must leave the corrupted managed lane untouched for operator repair"
    );
}
