fn authenticated_startup_state_for_testing(
    store_root: std::path::PathBuf,
    configured: &LaneCatalog,
) -> (Arc<Kura>, State) {
    let kura = authenticated_kura_for_testing(store_root, configured);
    let constructor_world = World::default();
    let_row! { mut state = State::try_new_with_chain(
    constructor_world.sccp_committee_generations.allocation_budget().clone(), constructor_world, Arc::clone(&kura), LiveQueryStore::start_test(), (*DEFAULT_TEST_CHAIN_ID).clone(), #[cfg(feature = "telemetry")] <_>::default(), ) .expect("construct production-like authenticated startup State") };
    state
        .prepare_configured_primary_geometry_anchor(configured)
        .expect("anchor authenticated configured primary");
    state
        .restore_kura_lane_segments_before_startup_replay()
        .expect("restore exact pre-replay primary geometry cursor");
    (kura, state)
}
#[test]
fn authenticated_startup_anchors_custom_primary_and_journals_secondaries_exactly_once() {
    let temp_dir = tempfile::tempdir().expect("temp dir");
    let store_root = temp_dir.path().join("authenticated-custom-primary-kura");
    let_row! { configured = LaneCatalog::new( nonzero!(2_u32), vec![ LaneConfig { alias: "configured-custom-primary".to_owned(), ..LaneConfig::default() }, LaneConfig { id: LaneId::new(1), alias: "configured-secondary".to_owned(), ..LaneConfig::default() }, ], ) .expect("custom-primary configured catalog") };
    for restart in 0..2 {
        let kura = authenticated_kura_for_testing(store_root.clone(), &configured);
        let constructor_world = World::default();
        let_row! { mut state = State::try_new_with_chain(
        constructor_world.sccp_committee_generations.allocation_budget().clone(), constructor_world, Arc::clone(&kura), LiveQueryStore::start_test(), (*DEFAULT_TEST_CHAIN_ID).clone(), #[cfg(feature = "telemetry")] <_>::default(), ) .expect("construct production-like authenticated startup State") };
        let secondary_blocks = fixture_static_storage_identity(&state, &configured, LaneId::new(1))
            .blocks_dir(&store_root);
        if restart == 0 {
            assert!(
                !secondary_blocks.exists(),
                "authenticated Kura defers fresh secondary storage"
            );
        }
        state
            .prepare_configured_primary_geometry_anchor(&configured)
            .expect("anchor exact authenticated primary");
        state
            .restore_kura_lane_segments_before_startup_replay()
            .expect("restore pre-replay primary geometry cursor");
        let anchored = state.nexus_snapshot();
        assert_eq!(anchored.lane_catalog.lanes().len(), 1);
        assert_eq!(
            anchored.lane_catalog.lanes()[0].alias,
            "configured-custom-primary"
        );
        assert_eq!(
            state.lane_incarnations_snapshot(),
            derive_static_lane_incarnations(&anchored.lane_catalog)
        );
        assert_eq!(
            state.lane_incarnation_activation_heights_snapshot(),
            BTreeMap::from([(LaneId::SINGLE, 0)])
        );
        state
            .set_nexus_from_config(startup_nexus_for_catalog(configured.clone()))
            .expect("journal every configured secondary from the authenticated primary");
        assert_eq!(state.nexus_snapshot().lane_catalog, configured);
        assert!(secondary_blocks.is_dir());
        assert_eq!(
            state.lane_storage_identity(LaneId::SINGLE),
            Some(fixture_static_storage_identity(
                &state,
                &LaneCatalog::new(configured.lane_count(), vec![configured.lanes()[0].clone()])
                    .unwrap(),
                LaneId::SINGLE
            )),
            "the original configured primary survives secondary catalog publication"
        );
        assert_eq!(
            std::fs::read_dir(store_root.join("blocks/instances"))
                .unwrap()
                .count(),
            2
        );
        assert_eq!(
            state.lane_incarnation_activation_heights_snapshot(),
            BTreeMap::from([(LaneId::SINGLE, 0), (LaneId::new(1), 0)])
        );
        let_row! { (baseline, phases, has_temp) = kura .lane_geometry_journal_state_for_test() .expect("authenticated startup journal state") };
        assert_eq!(
            baseline,
            Some(LaneLifecycleParameterV1::catalog_hash(&configured))
        );
        assert_eq!(phases, vec!["catalog_published"]);
        assert!(!has_temp);
    }
}
