fn invalid_startup_catalog_retains_authenticated_baseline_and_corrected_retry_succeeds() {
    let temp_dir = tempfile::tempdir().expect("temp dir");
    let_row! { store_root = temp_dir .path() .join("configured-baseline-invalid-retry-kura") };
    let dataspace_id = DataSpaceId::new(77);
    let_row! { configured = LaneCatalog::new( nonzero!(2_u32), vec![ LaneConfig::default(), LaneConfig { id: LaneId::new(1), alias: "correctable-startup-lane".to_owned(), dataspace_id, ..LaneConfig::default() }, ], ) .expect("catalog with a not-yet-declared dataspace") };
    let configured_hash = LaneLifecycleParameterV1::catalog_hash(&configured);
    let (kura, mut state) = authenticated_startup_state_for_testing(store_root, &configured);
    let_row! { err = state .set_nexus_from_config(startup_nexus_for_catalog(configured.clone())) .expect_err("invalid startup topology must fail before baseline publication") };
    assert!(
        matches!(err, LaneLifecycleError::UnknownDataspace(rejected) if rejected == dataspace_id),
        "unexpected startup rejection: {err:?}"
    );
    assert_eq!(
        kura.configured_lane_catalog_baseline()
            .expect("read authenticated baseline after invalid startup"),
        Some(configured_hash)
    );
    assert_eq!(state.nexus_snapshot().lane_catalog.lanes().len(), 1);
    state
        .set_nexus_from_config(iroha_config::parameters::actual::Nexus {
            lane_catalog: configured.clone(),
            configured_lane_catalog: configured.clone(),
            dataspace_catalog: dataspace_catalog_with_extra(dataspace_id),
            configured_dataspace_catalog: dataspace_catalog_with_extra(dataspace_id),
            ..Default::default()
        })
        .expect("corrected startup topology should publish the exact baseline");
    assert_eq!(state.nexus_snapshot().lane_catalog, configured);
    assert!(
        kura.configured_lane_catalog_baseline()
            .expect("read baseline after corrected retry")
            .is_some()
    );
}
