state_test! { sync emergency_fast_restored_config_rejects_dataspace_catalog_replacement
    let restored = iroha_config::parameters::actual::Nexus::default();
    let mut described = restored.clone();
    described.dataspace_catalog = DataSpaceCatalog::new(vec![DataSpaceMetadata {
        description: Some("local operator description".to_owned()),
        ..DataSpaceMetadata::default()
    }]).expect("description-only catalog");
    State::ensure_emergency_fast_restored_catalogs_match(&restored, &described)
        .expect("operator descriptions are outside canonical dataspace identity");
    for changed_field in 0..3 {
        let mut entry = DataSpaceMetadata::default();
        match changed_field {
            0 => entry.id = DataSpaceId::new(9),
            1 => entry.alias = "different-alias".to_owned(),
            _ => entry.fault_tolerance = 2,
        }
        let mut changed = restored.clone();
        changed.dataspace_catalog = DataSpaceCatalog::new(vec![entry])
            .expect("intrinsically valid changed dataspace policy");
        assert!(matches!(
            State::ensure_emergency_fast_restored_catalogs_match(&restored, &changed),
            Err(LaneLifecycleError::ConfiguredCatalogBaseline(message))
                if message.contains("dataspace catalog")
        ), "canonical dataspace field {changed_field} must remain exact");
    }
    let mut requested = restored.clone();
    requested.dataspace_catalog = DataSpaceCatalog::new(vec![
        DataSpaceMetadata {
            id: DataSpaceId::UNIVERSAL,
            alias: "universal".to_owned(),
            description: None,
            fault_tolerance: 1,
        },
        DataSpaceMetadata {
            id: DataSpaceId::new(7),
            alias: "replacement".to_owned(),
            description: None,
            fault_tolerance: 1,
        },
    ])
    .expect("replacement dataspace catalog");
    let error = State::ensure_emergency_fast_restored_catalogs_match(&restored, &requested)
        .expect_err("emergency Fast must preserve snapshot dataspace identity");
    assert!(matches!(
        error,
        LaneLifecycleError::ConfiguredCatalogBaseline(message)
            if message.contains("dataspace catalog")
    ));
}
state_test! { sync emergency_fast_restored_config_preserves_staking_owner_and_custody
    for pending_only in [false, true] {
        let (validator, keypair) = bls_account_in("emergency-staking");
        let custody_asset = AssetId::new(
            SumeragiNposParameters::default().xor_asset_definition_id,
            validator.clone(),
        );
        let mut world = World::default();
        let (id, account) = Account::new(validator.clone())
            .build(&validator)
            .into_key_value();
        world.accounts.insert(id, account);
        world = custody_fixture::registered_custody_world_for_test(
            world,
            &custody_asset,
            Quantity::from(100_u64),
        );
        {
            let mut parameters = world.parameters.block();
            parameters.set_parameter(iroha_data_model::parameter::Parameter::Custom(
                SumeragiNposParameters {
                    evidence_horizon_blocks: 1,
                    slashing_delay_blocks: 1,
                    ..SumeragiNposParameters::default()
                }
                .into_custom_parameter(),
            )).expect("valid fixture parameters");
            parameters.commit();
        }
        let mut state = State::new_for_testing(
            world,
            Kura::blank_kura_for_testing_in_emergency_fast_mode(),
            LiveQueryStore::start_test(),
        );
        state.nexus_runtime_restored_from_snapshot = true;
        insert_active_public_lane_validator_for_test(
            &state,
            LaneId::SINGLE,
            &validator,
            &keypair,
            100,
        );
        {
            let mut world = state.world.block();
            world.public_lane_stake_custody.insert(
                (LaneId::SINGLE, validator.clone()),
                (custody_asset.clone(), Quantity::from(100_u64)),
            );
            world
                .public_lane_stake_reserves
                .insert(custody_asset.clone(), Quantity::from(100_u64));
            if pending_only {
                let record = world
                    .public_lane_validators
                    .get_mut(&(LaneId::SINGLE, validator.clone()))
                    .unwrap();
                record.total_stake = Quantity::zero();
                record.self_stake = Quantity::zero();
                record.status = PublicLaneValidatorStatus::Exited;
                record.deactivation_height = Some(0);
                let share = world
                    .public_lane_stake_shares
                    .get_mut(&(LaneId::SINGLE, validator.clone(), validator.clone()))
                    .unwrap();
                share.bonded = Quantity::zero();
                let request_id = Hash::new(b"retained emergency pending unbond");
                share.pending_unbonds.insert(
                    request_id,
                    PublicLaneUnbonding {
                        request_id,
                        amount: Quantity::from(100_u64),
                        release_at_ms: 1000,
                        slashable_through_height: 1,
                        liability_release_height: 3,
                    },
                );
            }
            world.commit();
        }
        let before = state.nexus_snapshot();
        let mut changed_owner = before.clone();
        changed_owner.staking.public_validator_mode =
            iroha_config::parameters::actual::LaneValidatorMode::AdminManaged;
        let error = state
            .set_nexus_from_config(changed_owner)
            .expect_err("Fast recovery cannot remove a retained staking owner");
        assert!(
            matches!(error, LaneLifecycleError::UnsafeRetirement { lane, reason }
            if lane == LaneId::SINGLE && reason == LIVE_SHARED_DATASPACE_STAKING_OWNER_CHANGE_REASON)
        );
        assert_eq!(
            state.nexus_snapshot().staking.public_validator_mode,
            before.staking.public_validator_mode
        );
        assert_eq!(
            state
                .world
                .public_lane_stake_reserves
                .view()
                .get(&custody_asset),
            Some(&Quantity::from(100_u64))
        );

        let mut recoverable = before;
        recoverable.staking.stake_escrow_account_id = BOB_ID.to_string();
        state.set_nexus_from_config(recoverable)
            .expect("Fast recovery may update local selectors while pinned custody retains its exact source");
        assert_eq!(
            state
                .world
                .public_lane_stake_custody
                .view()
                .get(&(LaneId::SINGLE, validator)),
            Some(&(custody_asset, Quantity::from(100_u64)))
        );
    }
    let mut empty = State::new_for_testing(
        World::default(),
        Kura::blank_kura_for_testing_in_emergency_fast_mode(),
        LiveQueryStore::start_test(),
    );
    empty.nexus_runtime_restored_from_snapshot = true;
    let mut no_liability = empty.nexus_snapshot();
    no_liability.staking.public_validator_mode =
        iroha_config::parameters::actual::LaneValidatorMode::AdminManaged;
    empty
        .set_nexus_from_config(no_liability)
        .expect("Fast recovery may change a staking owner after all liabilities drain");
}

state_test! { sync restored_runtime_geometry_is_recovered_before_later_catalog_replay
    let temp_dir = tempfile::tempdir().expect("temp dir");
    let_row! { configured = LaneCatalog::new( nonzero!(3_u32), vec![ LaneConfig::default(), LaneConfig { id: LaneId::new(1), alias: "snapshot-lane".to_owned(), ..LaneConfig::default() }, ], ) .expect("configured snapshot catalog") };
    let_row! { (kura, mut state) = authenticated_startup_state_for_testing( temp_dir.path().join("older-snapshot-geometry-kura"), &configured, ) };
    state
        .set_nexus_from_config(startup_nexus_for_catalog(configured.clone()))
        .expect("publish configured geometry");
    let_row! { later_catalog = LaneCatalog::new( nonzero!(3_u32), vec![ LaneConfig::default(), configured.lanes()[1].clone(), LaneConfig { id: LaneId::new(2), alias: "post-snapshot-lane".to_owned(), ..LaneConfig::default() }, ], ) .expect("post-snapshot catalog") };
    let configured_runtime = RuntimeLaneConfig::from_catalog(&configured);
    let later_runtime = RuntimeLaneConfig::from_catalog(&later_catalog);
    let configured_incarnations = state.lane_incarnations_snapshot();
    let mut later_incarnations = configured_incarnations.clone();
    let later_incarnation = Hash::new(b"post-snapshot-incarnation");
    later_incarnations.insert(LaneId::new(2), later_incarnation);
    let configured_activations = state.lane_incarnation_activation_heights_snapshot();
    let mut later_activations = configured_activations.clone();
    later_activations.insert(LaneId::new(2), 1);
    let configured_lineage = state.lane_incarnation_lineage_snapshot();
    let mut later_lineage = configured_lineage.clone();
    later_lineage.insert(
        LaneId::new(2),
        LaneIncarnationLineage {
            generation: 0,
            incarnation: later_incarnation,
            activation_height: 1,
        },
    );
    let_row! { configured_lineage_root = lane_incarnation_lineage_root(state.network_id_ref(), &configured_lineage) };
    let later_lineage_root = lane_incarnation_lineage_root(state.network_id_ref(), &later_lineage);
    kura.apply_lane_geometry_transition_at_height_with_lineage_roots(
        &configured_runtime,
        &later_runtime,
        &configured_incarnations,
        &later_incarnations,
        &configured_activations,
        &later_activations,
        configured_lineage_root,
        later_lineage_root,
        &BTreeSet::new(),
        1,
    )
    .expect("publish a transition newer than the restored snapshot");
    kura.mark_lane_geometry_catalog_published_with_lineage_root(
        &later_runtime,
        &later_incarnations,
        &later_activations,
        later_lineage_root,
        None,
    )
    .expect("mark post-snapshot geometry published");
    let later_identity = crate::kura::LaneStorageIdentity {
        network_id: *state.network_id_ref(), lane_id: LaneId::new(2), dataspace_id: DataSpaceId::UNIVERSAL,
        incarnation: later_incarnation, activation_height: 1,
    };
    let later_blocks = later_identity.blocks_dir(&kura.store_root());
    assert!(later_blocks.is_dir());
    state.nexus_runtime_restored_from_snapshot = true;
    state
        .prepare_restored_configured_primary_geometry_anchor(&configured)
        .expect("authenticate restored primary before geometry recovery");
    state
        .restore_kura_lane_segments_from_nexus()
        .expect("restore the older snapshot cursor before applying startup config");
    assert!(
        later_blocks.is_dir(),
        "snapshot rollback retains the exact post-snapshot instance for replay"
    );
    assert!(state.lane_storage_identity(LaneId::new(2)).is_none());
    let restored = state.nexus_snapshot();
    state
        .set_nexus_from_config(restored)
        .expect("startup policy overlay retains the authenticated restored topology");
    assert_eq!(state.nexus_snapshot().lane_catalog, configured);
}
state_test! { sync configured_lane_catalog_is_immutable_across_runtime_updates
    let temp_dir = tempfile::tempdir().expect("temporary authenticated Kura root");
    let_row! { configured_catalog = LaneCatalog::new( nonzero!(2_u32), vec![ LaneConfig::default(), LaneConfig { id: LaneId::new(1), alias: "configured-lane".to_owned(), ..LaneConfig::default() }, ], ) .expect("configured lane catalog") };
    let_row! { (_, mut state) = authenticated_startup_state_for_testing( temp_dir.path().join("immutable-configured-catalog-kura"), &configured_catalog, ) };
    state
        .set_nexus_from_config(iroha_config::parameters::actual::Nexus {
            lane_catalog: configured_catalog.clone(),
            configured_lane_catalog: configured_catalog.clone(),
            ..Default::default()
        })
        .expect("install startup Nexus configuration");
    let mut attempted_runtime_rebind = state.nexus_snapshot();
    attempted_runtime_rebind.configured_lane_catalog = LaneCatalog::default();
    state
        .set_nexus(attempted_runtime_rebind)
        .expect("apply runtime Nexus overlay");
    assert_eq!(
        state.nexus_snapshot().configured_lane_catalog,
        configured_catalog,
        "runtime overlays must not replace the process-configured baseline"
    );
    state
        .apply_lane_lifecycle(&iroha_data_model::nexus::LaneLifecyclePlan {
            additions: vec![LaneConfig {
                id: LaneId::new(2),
                alias: "runtime-lane".to_owned(),
                ..LaneConfig::default()
            }],
            retire: Vec::new(),
        })
        .expect("apply runtime lane lifecycle");
    let nexus = state.nexus_snapshot();
    assert_eq!(nexus.configured_lane_catalog, configured_catalog);
    assert_eq!(nexus.lane_catalog.lanes().len(), 3);
}
