state_test! { sync set_nexus_prunes_space_directory_manifests_for_removed_dataspaces
    let retained = DataSpaceId::UNIVERSAL;
    let removed = DataSpaceId::new(7);
    let uaid_mixed = UniversalAccountId::from_hash(Hash::new(b"uaid::mixed-manifests"));
    let uaid_stale_only = UniversalAccountId::from_hash(Hash::new(b"uaid::stale-only-manifests"));
    let initial_nexus = dataspace_retirement_nexus!(initial retained, removed);
    let mut state = State::new_with_pre_genesis_nexus_for_testing(
        World::default(), initial_nexus, LiveQueryStore::start_test(),
    );
    assert_eq!(state.committed_height(), 0);
    let_row! { manifest_record = |uaid: UniversalAccountId, dataspace: DataSpaceId| { let manifest = AssetPermissionManifest { version: ManifestVersion::default(), uaid, dataspace, issued_ms: 1, activation_epoch: 1, expiry_epoch: None, entries: Vec::new(), }; let mut record = SpaceDirectoryManifestRecord::new(manifest); record.lifecycle.mark_activated(1); record } };
    let mut mixed_set = SpaceDirectoryManifestSet::default();
    mixed_set.upsert(manifest_record(uaid_mixed, retained));
    mixed_set.upsert(manifest_record(uaid_mixed, removed));
    let mut stale_only_set = SpaceDirectoryManifestSet::default();
    stale_only_set.upsert(manifest_record(uaid_stale_only, removed));
    let mut wb = state.world.block();
    wb.space_directory_manifests.insert(uaid_mixed, mixed_set);
    wb.space_directory_manifests
        .insert(uaid_stale_only, stale_only_set);
    wb.commit();
    let mut updated_nexus = dataspace_retirement_nexus!(retained retained);
    updated_nexus.configured_dataspace_catalog = updated_nexus.dataspace_catalog.clone();
    // Only fresh pre-genesis configuration may replace the physical baseline.
    assert!(matches!(
        state.set_nexus(updated_nexus.clone()),
        Err(LaneLifecycleError::RuntimeCatalog(_)),
    ));
    state
        .set_nexus_from_config(updated_nexus)
        .expect("set updated nexus config");
    let manifests_view = state.world.space_directory_manifests.view();
    let_row! { mixed = manifests_view .get(&uaid_mixed) .expect("mixed manifest set should remain for retained dataspace") };
    assert!(
        mixed.get(&retained).is_some(),
        "retained dataspace manifest should remain"
    );
    assert!(
        mixed.get(&removed).is_none(),
        "removed dataspace manifest should be pruned"
    );
    assert!(
        manifests_view.get(&uaid_stale_only).is_none(),
        "manifest set should be removed when all dataspaces are stale"
    );
}
state_test! { sync configured_startup_prunes_account_scope_directory_for_removed_dataspaces
    let retained = DataSpaceId::UNIVERSAL;
    let removed = DataSpaceId::new(7);
    let mixed_account = AccountId::new(crate::state::checked_keypair().public_key().clone());
    let stale_only_account = AccountId::new(crate::state::checked_keypair().public_key().clone());
    let initial_nexus = dataspace_retirement_nexus!(initial retained, removed);
    let mut world = World::default();
    for account in [&mixed_account, &stale_only_account] {
        world.accounts.insert(
            account.clone(),
            AccountValue::new(iroha_data_model::account::AccountDetails::default()),
        );
    }
    let mut state = State::new_with_pre_genesis_nexus_for_testing(
        world,
        initial_nexus,
        LiveQueryStore::start_test(),
    );
    assert_eq!(state.committed_height(), 0);
    let mut mixed_entry = AccountScopeDirectoryEntry::default();
    mixed_entry.ensure_dataspace(retained);
    mixed_entry.ensure_dataspace(removed);
    let mut stale_only_entry = AccountScopeDirectoryEntry::default();
    stale_only_entry.ensure_dataspace(removed);
    let mut wb = state.world.block();
    wb.account_scope_directory
        .insert(mixed_account.clone(), mixed_entry);
    wb.account_scope_directory
        .insert(stale_only_account.clone(), stale_only_entry);
    wb.commit();
    let mut updated_nexus = dataspace_retirement_nexus!(retained retained);
    updated_nexus.configured_dataspace_catalog = updated_nexus.dataspace_catalog.clone();
    // Physical baseline changes belong to pre-genesis configuration installation.
    // The ordinary setter must continue rejecting this change.
    assert!(matches!(
        state.set_nexus(updated_nexus.clone()),
        Err(LaneLifecycleError::RuntimeCatalog(_))
    ));
    state
        .set_nexus_from_config(updated_nexus)
        .expect("reconcile the validated pre-genesis configuration");
    assert_eq!(state.committed_height(), 0);
    let view = state.world.account_scope_directory.view();
    let_row! { mixed = view .get(&mixed_account) .expect("mixed account scope entry should remain") };
    assert!(
        mixed
            .iter()
            .all(|(dataspace_id, _)| *dataspace_id == retained),
        "stale dataspaces should be pruned from mixed account scope entries",
    );
    assert!(
        view.get(&stale_only_account).is_none(),
        "entries should be removed when every dataspace becomes stale",
    );
}
#[derive(Clone, Copy)]
enum LaneDataspaceChangeRoute {
    SetNexus,
    Lifecycle,
}
fn assert_lane_state_retained_on_rejected_dataspace_change(route: LaneDataspaceChangeRoute) {
    let_row! { _status_guard = crate::status::nexus_fee_test_lock() .lock() .expect("nexus status test lock") };
    crate::status::reset_nexus_economics_for_tests();
    let retained = DataSpaceId::UNIVERSAL;
    let migrated = match route {
        LaneDataspaceChangeRoute::SetNexus => DataSpaceId::new(9),
        LaneDataspaceChangeRoute::Lifecycle => DataSpaceId::new(11),
    };
    let reset_lane = LaneId::new(1);
    let_row! { initial_nexus = iroha_config::parameters::actual::Nexus { lane_catalog: LaneCatalog::new( nonzero!(2_u32), vec![ LaneConfig::default(), LaneConfig { id: reset_lane, alias: "lane1-retained".to_string(), ..LaneConfig::default() }, ], ) .expect("lane catalog"), dataspace_catalog: DataSpaceCatalog::new(vec![ DataSpaceMetadata { id: retained, alias: "universal".to_string(), description: None, fault_tolerance: 1, }, DataSpaceMetadata { id: migrated, alias: "migrated".to_string(), description: None, fault_tolerance: 1, }, ]) .expect("dataspace catalog"), ..iroha_config::parameters::actual::Nexus::default() } };
    let state = State::new_with_nexus_for_testing(
        World::default(),
        initial_nexus,
        LiveQueryStore::start_test(),
    );
    {
        let mut commitments = state.da_commitments.write();
        let_row! { record = DaCommitmentRecord::new( reset_lane, 1, 0, BlobDigest::new([0xAA; 32]), ManifestDigest::new([0xBB; 32]), DaProofScheme::MerkleSha256, Hash::prehashed([0xCC; 32]), None, RetentionClass::default(), StorageTicketId::new([0xEE; 32]), checked_da_ack_signature(0x11), ) };
        commitments.insert(
            &record,
            DaCommitmentLocation {
                block_height: 3,
                index_in_bundle: 0,
            },
        );
        state.da_confidential_compute.write().insert(
            &record,
            DaCommitmentLocation {
                block_height: 3,
                index_in_bundle: 1,
            },
            &ConfidentialComputePolicy::new(
                ConfidentialComputeMechanism::Encryption,
                NonZeroU32::new(7).expect("non-zero key version"),
                BTreeSet::new(),
            ),
        );
    }
    {
        let mut intents = state.da_pin_intents.write();
        let_row! { mut intent = test_da_pin_intent( *state.network_id_ref(), reset_lane, 1, 1, StorageTicketId::new([0x44; 32]), ManifestDigest::new([0x55; 32]), ) };
        let alias = match route {
            LaneDataspaceChangeRoute::SetNexus => "lane1-reassign",
            LaneDataspaceChangeRoute::Lifecycle => "lane1-lifecycle-reassign",
        };
        set_test_da_pin_intent_alias(&mut intent, &ALICE_KEYPAIR, Some(alias.to_owned()));
        intents.insert(
            intent,
            DaCommitmentLocation {
                block_height: 3,
                index_in_bundle: 2,
            },
        );
    }
    let reset_status_bonded = Quantity::from(match route {
        LaneDataspaceChangeRoute::SetNexus => 909_u32,
        LaneDataspaceChangeRoute::Lifecycle => 911_u32,
    });
    record_public_lane_staking_status_for_test(reset_lane, &reset_status_bonded);
    match route {
        LaneDataspaceChangeRoute::SetNexus => {
            let_row! { updated_nexus = iroha_config::parameters::actual::Nexus { lane_catalog: LaneCatalog::new( nonzero!(2_u32), vec![ LaneConfig::default(), LaneConfig { id: reset_lane, dataspace_id: migrated, alias: "lane1-migrated".to_string(), ..LaneConfig::default() }, ], ) .expect("lane catalog"), dataspace_catalog: DataSpaceCatalog::new(vec![ DataSpaceMetadata { id: retained, alias: "universal".to_string(), description: None, fault_tolerance: 1, }, DataSpaceMetadata { id: migrated, alias: "migrated".to_string(), description: None, fault_tolerance: 1, }, ]) .expect("dataspace catalog"), ..iroha_config::parameters::actual::Nexus::default() } };
            state
                .apply_lane_lifecycle(&iroha_data_model::nexus::LaneLifecyclePlan {
                    additions: vec![
                        updated_nexus
                            .lane_catalog
                            .lanes()
                            .iter()
                            .find(|lane| lane.id == reset_lane)
                            .expect("replacement lane")
                            .clone(),
                    ],
                    retire: vec![reset_lane],
                })
                .expect_err("physical lane replacement must fail closed");
        }
        LaneDataspaceChangeRoute::Lifecycle => {
            let_row! { plan = iroha_data_model::nexus::LaneLifecyclePlan { additions: vec![LaneConfig { id: reset_lane, dataspace_id: migrated, alias: "lane1-migrated".to_string(), ..LaneConfig::default() }], retire: vec![reset_lane], } };
            state
                .apply_lane_lifecycle(&plan)
                .expect_err("physical lane replacement must fail closed");
            let nexus_snapshot = state.nexus_snapshot();
            let_row! { lane_entry = nexus_snapshot .lane_config .entry(reset_lane) .expect("lane must remain after reassign") };
            assert_eq!(lane_entry.dataspace_id, retained);
        }
    }
    assert!(
        state
            .da_commitments
            .read()
            .get_by_lane_epoch_sequence(reset_lane.as_u32(), 1, 0)
            .is_some(),
        "lane commitments must be retained after rejected dataspace replacement"
    );
    assert!(
        state
            .da_confidential_compute
            .read()
            .get_by_lane_epoch_sequence(reset_lane.as_u32(), 1, 0)
            .is_some(),
        "lane confidential receipts must be retained after rejected dataspace replacement"
    );
    assert!(
        state
            .da_pin_intents
            .read()
            .get_by_alias(match route {
                LaneDataspaceChangeRoute::SetNexus => "lane1-reassign",
                LaneDataspaceChangeRoute::Lifecycle => "lane1-lifecycle-reassign",
            })
            .is_some(),
        "lane pin intents must be retained after rejected dataspace replacement"
    );
    assert_public_lane_staking_status_bonded(
        reset_lane,
        &reset_status_bonded,
        "rejected physical replacement preserves staking status",
    );
    crate::status::reset_nexus_economics_for_tests();
}
#[test]
fn set_nexus_preserves_lane_state_when_dataspace_replacement_is_rejected() {
    assert_lane_state_retained_on_rejected_dataspace_change(LaneDataspaceChangeRoute::SetNexus);
}
#[test]
fn apply_lane_lifecycle_preserves_state_when_dataspace_replacement_is_rejected() {
    assert_lane_state_retained_on_rejected_dataspace_change(LaneDataspaceChangeRoute::Lifecycle);
}
