state_test! { sync set_nexus_rejects_configured_lane_retirement_without_pruning_da_pin_intents
    let retired_lane_id = LaneId::new(1);
    let_row! { initial_catalog = LaneCatalog::new( nonzero!(2_u32), vec![ LaneConfig::default(), LaneConfig { id: retired_lane_id, alias: "set-nexus-pin-lane".to_string(), ..LaneConfig::default() }, ], ) .expect("initial lane catalog") };
    let mut state = State::new_with_nexus_for_testing(
        World::default(),
        iroha_config::parameters::actual::Nexus { lane_catalog: initial_catalog, ..Default::default() },
        LiveQueryStore::start_test(),
    );
    let_row! { mut retired_intent = test_da_pin_intent( *state.network_id_ref(), retired_lane_id, 5, 0, StorageTicketId::new([0x63; 32]), ManifestDigest::new([0x73; 32]), ) };
    set_test_da_pin_intent_alias(
        &mut retired_intent,
        &ALICE_KEYPAIR,
        Some("set-nexus-retired-pin".to_owned()),
    );
    let_row! { mut retained_intent = test_da_pin_intent( *state.network_id_ref(), LaneId::SINGLE, 5, 1, StorageTicketId::new([0x64; 32]), ManifestDigest::new([0x74; 32]), ) };
    set_test_da_pin_intent_alias(
        &mut retained_intent,
        &ALICE_KEYPAIR,
        Some("set-nexus-retained-pin".to_owned()),
    );
    seed_da_pin_intent_world_indexes_for_test(&state, retired_intent.clone(), 4, 0);
    seed_da_pin_intent_world_indexes_for_test(&state, retained_intent.clone(), 4, 1);
    assert!(matches!(
        state.set_nexus(iroha_config::parameters::actual::Nexus {
            lane_catalog: LaneCatalog::default(),
            ..Default::default()
        }),
        Err(LaneLifecycleError::ConfiguredCatalogBaseline(_))
    ));
    assert!(state.nexus_snapshot().lane_catalog.lanes().iter().any(|lane| lane.id == retired_lane_id));
    let view = state.view();
    let world = view.world();
    assert!(
        world
            .da_pin_intents_by_ticket()
            .get(&retired_intent.storage_ticket)
            .is_some(),
        "rejected configured retirement must preserve pin intent tickets"
    );
    assert!(
        world
            .da_pin_intents_by_alias()
            .get("set-nexus-retired-pin")
            .is_some(),
        "rejected configured retirement must preserve pin intent aliases"
    );
    assert!(
        world
            .da_pin_intents_by_manifest()
            .get(&retired_intent.manifest_hash)
            .is_some(),
        "rejected configured retirement must preserve pin intent manifests"
    );
    assert!(
        world
            .da_pin_intents_by_lane_epoch()
            .get(&(
                retired_intent.lane_id,
                retired_intent.epoch,
                retired_intent.sequence,
            ))
            .is_some(),
        "rejected configured retirement must preserve pin intent lane-epoch indexes"
    );
    assert!(
        world
            .da_pin_intents_by_ticket()
            .get(&retained_intent.storage_ticket)
            .is_some(),
        "rejected configured retirement must preserve active-lane pin intent tickets"
    );
    assert_eq!(
        world
            .da_pin_intents_by_alias()
            .get("set-nexus-retained-pin"),
        Some(&retained_intent.storage_ticket)
    );
    assert_eq!(
        world
            .da_pin_intents_by_manifest()
            .get(&retained_intent.manifest_hash),
        Some(&retained_intent.storage_ticket)
    );
    assert_eq!(
        world.da_pin_intents_by_lane_epoch().get(&(
            retained_intent.lane_id,
            retained_intent.epoch,
            retained_intent.sequence,
        )),
        Some(&retained_intent.storage_ticket)
    );
}

fn install_lane_manifest_registry(state: &State, lanes: &[(LaneId, DataSpaceId, Vec<AccountId>)]) {
    let nexus = state.nexus_snapshot();
    let mut bindings_by_lane = BTreeMap::new();
    for (lane_id, dataspace_id, validators) in lanes {
        let lane = nexus
            .lane_catalog
            .lanes()
            .iter()
            .find(|lane| lane.id == *lane_id)
            .expect("manifest fixture requires an actual configured lane");
        assert_eq!(
            lane.dataspace_id, *dataspace_id,
            "manifest fixture binds the exact route"
        );
        let_row! { validator_bindings = validators .iter() .map(|validator| ManifestValidatorBinding { validator: validator.clone(), peer_id: PeerId::from( validator .try_signatory() .expect("manifest test validators must be single-signatory") .clone(), ), torii_url: None, }) .collect() };
        bindings_by_lane.insert(*lane_id, validator_bindings);
    }
    let registry = Arc::new(
        crate::governance::manifest::test_support::validator_registry(
            &nexus.lane_catalog,
            &nexus.governance,
            bindings_by_lane,
        ),
    );
    state.install_lane_manifests_for_testing(&registry);
}
/// Construct isolated stale route claims; they must never be installed as native authority.
fn stale_lane_manifest_registry_for_test(
    state: &State,
    lanes: &[(LaneId, DataSpaceId, Vec<AccountId>)],
) -> LaneManifestRegistryHandle {
    let nexus = state.nexus_snapshot();
    let statuses = lanes
        .iter()
        .map(|(lane_id, dataspace_id, validators)| {
            let lane = nexus
                .lane_catalog
                .lanes()
                .iter()
                .find(|lane| lane.id == *lane_id);
            let status = LaneManifestStatus {
                lane: *lane_id,
                alias: lane.map_or_else(
                    || format!("stale-lane-{}", lane_id.as_u32()),
                    |lane| lane.alias.clone(),
                ),
                dataspace: *dataspace_id,
                visibility: lane.map_or(LaneVisibility::Public, |lane| lane.visibility),
                storage: lane.map_or(LaneStorageProfile::FullReplica, |lane| lane.storage),
                governance: lane.and_then(|lane| lane.governance.clone()),
                manifest_path: Some(std::path::PathBuf::from("/tmp/stale-manifest.json")),
                governance_rules: Some(GovernanceRules {
                    validators: validators.clone(),
                    validator_bindings: validators
                        .iter()
                        .map(|validator| ManifestValidatorBinding {
                            validator: validator.clone(),
                            peer_id: peer_id_for_account(validator),
                            torii_url: None,
                        })
                        .collect(),
                    ..GovernanceRules::default()
                }),
                privacy_commitments: Vec::new(),
            };
            (*lane_id, status)
        })
        .collect();
    Arc::new(LaneManifestRegistry::from_statuses(statuses))
}
fn install_lane_manifest_registry_for_keypairs(
    state: &State,
    lane_ids: &[LaneId],
    keypairs: &[KeyPair],
) {
    let_row! { validators = keypairs .iter() .map(|keypair| AccountId::new(keypair.public_key().clone())) .collect::<Vec<_>>() };
    let nexus = state.nexus_snapshot();
    let_row! { lanes = lane_ids .iter() .map(|lane_id| { let dataspace_id = nexus_catalog_geometry_lane_dataspace(*lane_id, &nexus) .expect("manifest fixture lane must exist in the Nexus catalog"); (*lane_id, dataspace_id, validators.clone()) }) .collect::<Vec<_>>() };
    install_lane_manifest_registry(state, &lanes);
}
fn install_lane_manifest_registry_with_bindings(
    state: &State,
    lane_id: LaneId,
    dataspace_id: DataSpaceId,
    validators: Vec<AccountId>,
    validator_bindings: Vec<ManifestValidatorBinding>,
) {
    let nexus = state.nexus_snapshot();
    let lane = nexus
        .lane_catalog
        .lanes()
        .iter()
        .find(|lane| lane.id == lane_id)
        .expect("manifest fixture requires an actual configured lane");
    assert_eq!(
        lane.dataspace_id, dataspace_id,
        "manifest fixture binds the exact route"
    );
    assert_eq!(
        validators,
        validator_bindings
            .iter()
            .map(|binding| binding.validator.clone())
            .collect::<Vec<_>>(),
        "valid fixture retains the exact declared validator order"
    );
    let registry = Arc::new(
        crate::governance::manifest::test_support::validator_registry(
            &nexus.lane_catalog,
            &nexus.governance,
            BTreeMap::from([(lane_id, validator_bindings)]),
        ),
    );
    state.install_lane_manifests_for_testing(&registry);
}
/// Exercise the canonical live-binding validator with an isolated malformed source.
fn isolated_manifest_validator_bindings(
    state: &State,
    registry: &LaneManifestRegistry,
    lane_id: LaneId,
) -> Vec<ManifestValidatorBinding> {
    let height = state.lane_authority_height();
    let Some(inputs) = state.lane_authority_inputs(lane_id, height) else {
        return Vec::new();
    };
    let Ok(Some(rules)) = lane_authority::manifest_rules_for_lane(lane_id, registry, &inputs)
    else {
        return Vec::new();
    };
    bounded_authority::live_manifest_validator_bindings(
        &state.world.view(),
        lane_id,
        &rules.validator_bindings,
        &rules.validators,
        height,
    )
}
/// Exercise the canonical account projection without materializing a malformed State.
fn isolated_manifest_validator_accounts(
    state: &State,
    registry: &LaneManifestRegistry,
    lane_id: LaneId,
) -> Vec<AccountId> {
    let height = state.lane_authority_height();
    let Some(inputs) = state.lane_authority_inputs(lane_id, height) else {
        return Vec::new();
    };
    lane_authority::validator_accounts_with_inputs(
        &state.world.view(),
        lane_id,
        registry,
        &inputs,
        height,
    )
}
