state_test! { sync lifecycle_rejects_resetting_live_shared_dataspace_staking_owner_atomically
    let kura = Kura::blank_kura_for_testing();
    let query_handle = LiveQueryStore::start_test();
    let mut state = State::new_for_testing(World::default(), kura, query_handle);
    let owner_lane = LaneId::new(1);
    let sibling_lane = LaneId::new(2);
    let shared_dataspace = DataSpaceId::new(9);
    configure_pre_genesis_nexus_fixture(&mut state, iroha_config::parameters::actual::Nexus {
            lane_catalog: LaneCatalog::new(
                nonzero!(3_u32),
                vec![
                    LaneConfig::default(),
                    LaneConfig {
                        id: owner_lane,
                        alias: "shared-staking-owner".to_owned(),
                        dataspace_id: shared_dataspace,
                        visibility: LaneVisibility::Public,
                        ..LaneConfig::default()
                    },
                    LaneConfig {
                        id: sibling_lane,
                        alias: "shared-staking-survivor".to_owned(),
                        dataspace_id: shared_dataspace,
                        visibility: LaneVisibility::Public,
                        ..LaneConfig::default()
                    },
                ],
            )
            .expect("shared-dataspace lifecycle catalog"),
            dataspace_catalog: DataSpaceCatalog::new(vec![
                DataSpaceMetadata::default(),
                DataSpaceMetadata {
                    id: shared_dataspace,
                    alias: "shared-staking".to_owned(),
                    description: None,
                    fault_tolerance: 1,
                },
            ])
            .expect("shared-dataspace lifecycle dataspace catalog"),
            ..iroha_config::parameters::actual::Nexus::default()
        });
    let (validator, keypair) = bls_account_in("validators");
    insert_active_public_lane_validator_for_test(
        &state, owner_lane, &validator, &keypair, 1_000_000,
    );
    let catalog_before = state.nexus_snapshot().lane_catalog;
    let validator_before = state
        .world
        .public_lane_validators
        .view()
        .get(&(owner_lane, validator.clone()))
        .expect("live owner validator")
        .clone();

    let retire = iroha_data_model::nexus::LaneLifecyclePlan {
        additions: Vec::new(),
        retire: vec![owner_lane],
    };
    let replace = iroha_data_model::nexus::LaneLifecyclePlan {
        additions: vec![LaneConfig {
            id: owner_lane,
            alias: "shared-staking-owner-replacement".to_owned(),
            dataspace_id: shared_dataspace,
            visibility: LaneVisibility::Public,
            ..LaneConfig::default()
        }],
        retire: vec![owner_lane],
    };

    {
        let updated_catalog = catalog_before
            .apply_lifecycle(&retire)
            .expect("owner retirement yields a catalog retaining the sibling");
        let nexus = state.nexus_snapshot();
        let mut prospective_nexus = nexus.clone();
        prospective_nexus.lane_catalog = updated_catalog;
        prospective_nexus.lane_config =
            RuntimeLaneConfig::from_catalog(&prospective_nexus.lane_catalog);
        let world = state.world.view();
        let err = ensure_live_shared_dataspace_staking_owner_is_not_reset(
            &world,
            &nexus,
            &prospective_nexus,
            &BTreeSet::from([owner_lane]),
            0,
        )
        .expect_err("the direct lifecycle guard must reject the live owner reset");
        assert!(matches!(
            err,
            LaneLifecycleError::UnsafeRetirement { lane, reason }
                if lane == owner_lane
                    && reason == LIVE_LANE_STAKING_CUSTODY_REASON
        ));
    }

    for (operation, plan) in [("retire", retire), ("replace", replace)] {
        let err = match state.apply_lane_lifecycle(&plan) {
            Ok(()) => panic!("{operation} unexpectedly reset the live owner"),
            Err(err) => err,
        };
        assert!(matches!(
            err,
            LaneLifecycleError::UnsafeRetirement { lane, reason }
                if lane == owner_lane
                    && reason.contains("physical catalog retirement")
        ));
        assert_eq!(state.nexus_snapshot().lane_catalog, catalog_before);
        let world = state.world.view();
        assert_eq!(
            world
                .public_lane_validators()
                .get(&(owner_lane, validator.clone())),
            Some(&validator_before),
            "rejected {operation} must preserve the live owner row"
        );
    }
}

state_test! { sync lifecycle_rejects_full_dataspace_retirement_with_exited_pending_unbond_custody
    let kura = Kura::blank_kura_for_testing();
    let query_handle = LiveQueryStore::start_test();
    let mut state = State::new_for_testing(World::default(), kura, query_handle);
    let lane_id = LaneId::new(1);
    let dataspace_id = DataSpaceId::new(9);
    configure_pre_genesis_nexus_fixture(&mut state, iroha_config::parameters::actual::Nexus {
            lane_catalog: LaneCatalog::new(
                nonzero!(2_u32),
                vec![
                    LaneConfig::default(),
                    LaneConfig {
                        id: lane_id,
                        alias: "retired-dataspace-owner".to_owned(),
                        dataspace_id,
                        visibility: LaneVisibility::Public,
                        ..LaneConfig::default()
                    },
                ],
            )
            .expect("two-dataspace lifecycle catalog"),
            dataspace_catalog: DataSpaceCatalog::new(vec![
                DataSpaceMetadata::default(),
                DataSpaceMetadata {
                    id: dataspace_id,
                    alias: "retired-dataspace".to_owned(),
                    description: None,
                    fault_tolerance: 1,
                },
            ])
            .expect("two-dataspace lifecycle dataspace catalog"),
            ..iroha_config::parameters::actual::Nexus::default()
        });
    let (validator, keypair) = bls_account_in("validators");
    let request_id = Hash::new("retired-dataspace-pending-unbond");
    {
        let mut world = state.world.block();
        world.public_lane_validators.insert(
            (lane_id, validator.clone()),
            PublicLaneValidatorRecord {
                lane_id,
                validator: validator.clone(),
                peer_id: PeerId::new(keypair.public_key().clone()),
                stake_account: validator.clone(),
                total_stake: Quantity::zero(),
                self_stake: Quantity::zero(),
                metadata: Metadata::default(),
                status: PublicLaneValidatorStatus::Exited,
                activation_height: 0,
                election_exit_height: Some(2),
                deactivation_height: Some(2),
            },
        );
        world.public_lane_stake_shares.insert(
            (lane_id, validator.clone(), validator.clone()),
            PublicLaneStakeShare {
                lane_id,
                validator: validator.clone(),
                staker: validator.clone(),
                bonded: Quantity::zero(),
                pending_unbonds: BTreeMap::from([(
                    request_id,
                    PublicLaneUnbonding {
                        request_id,
                        amount: Quantity::from(1_000_000_u64),
                        release_at_ms: 100,
                        slashable_through_height: 2,
                        liability_release_height: 3,
                    },
                )]),
                metadata: Metadata::default(),
            },
        );
        world.commit();
    }
    let catalog_before = state.nexus_snapshot().lane_catalog;
    let plan = iroha_data_model::nexus::LaneLifecyclePlan {
        additions: Vec::new(),
        retire: vec![lane_id],
    };

    let err = state
        .apply_lane_lifecycle(&plan)
        .expect_err("full dataspace retirement must retain pending-unbond custody");
    assert!(matches!(
        err,
        LaneLifecycleError::UnsafeRetirement { lane, reason }
            if lane == lane_id && reason.contains("physical catalog retirement")
    ));
    assert_eq!(state.nexus_snapshot().lane_catalog, catalog_before);
    let world = state.world.view();
    assert!(
        world
            .public_lane_validators()
            .get(&(lane_id, validator.clone()))
            .is_some(),
        "rejected retirement must preserve the exited validator audit row"
    );
    assert!(
        world
            .public_lane_stake_shares()
            .get(&(lane_id, validator.clone(), validator))
            .is_some_and(|share| share.pending_unbonds.contains_key(&request_id)),
        "rejected retirement must preserve pending-unbond custody"
    );
}

