fn autoscale_elastic_catalog_lane_with_committee_for_test(
    lane_id: LaneId,
    created_height: u64,
    keypairs: &[KeyPair],
) -> iroha_data_model::nexus::LaneConfig {
    let mut lane = autoscale_elastic_catalog_lane_for_test(lane_id, created_height);
    let mut members = keypairs.to_vec();
    members.sort_by(|left, right| {
        PeerId::new(left.public_key().clone()).cmp(&PeerId::new(right.public_key().clone()))
    });
    let_row! { validator_set = members .iter() .map(|keypair| PeerId::new(keypair.public_key().clone())) .collect::<Vec<_>>() };
    let_row! { validator_pops = members .iter() .map(|keypair| { iroha_crypto::bls_normal_pop_prove(keypair.private_key()) .expect("test autoscale committee PoP") }) .collect::<Vec<_>>() };
    let_row! { committee = autoscale_lane_committee_from_validator_set(validator_set, validator_pops) .expect("test autoscale committee") };
    lane.metadata.insert(
        AUTOSCALE_META_COMMITTEE.to_owned(),
        encode_autoscale_lane_committee(&committee).expect("test committee encoding"),
    );
    lane
}
fn install_autoscale_elastic_catalog_for_test(
    state: &State,
    lane: iroha_data_model::nexus::LaneConfig,
) {
    install_autoscale_elastic_lanes_for_test(state, vec![lane]);
}
fn install_autoscale_elastic_lanes_for_test(
    state: &State,
    lanes: Vec<iroha_data_model::nexus::LaneConfig>,
) {
    let_row! { lane_count = lanes .iter() .map(|lane| lane.id.as_u32()) .max() .unwrap_or(0) .saturating_add(1) };
    let mut catalog_lanes = Vec::with_capacity(lanes.len().saturating_add(1));
    catalog_lanes.push(iroha_data_model::nexus::LaneConfig::default());
    catalog_lanes.extend(lanes);
    let_row! { lane_catalog = LaneCatalog::new( core::num::NonZeroU32::new(lane_count).expect("nonzero lane count"), catalog_lanes, ) .expect("autoscale lane catalog") };
    let mut nexus = state.nexus_snapshot();
    nexus.autoscale.enabled = true;
    nexus.autoscale.min_lane_id = nonzero!(1_u32);
    nexus.autoscale.max_lane_id_exclusive =
        core::num::NonZeroU32::new(lane_count).expect("nonzero autoscale lane bound");
    nexus.lane_catalog = lane_catalog;
    nexus.lane_config =
        iroha_config::parameters::actual::LaneConfig::from_catalog(&nexus.lane_catalog);
    install_existing_nexus_geometry_for_test(state, nexus);
}
