#[test]
fn authoritative_lane_peers_for_autoscale_elastic_lane_pin_creation_manifest_committee() {
    let state = blank_test_state();
    let lane_id = LaneId::new(1);
    install_autoscale_elastic_catalog_for_test(
        &state,
        autoscale_elastic_catalog_lane_for_test(lane_id, 1),
    );
    let height = seed_lane_committee_beacon_for_test(&state);
    seed_latest_lane_authority_height_for_test(&state, height);
    let (manifest_validators, manifest_keypairs) = bls_accounts_in("validators", 6);
    let_row! { topology_keypairs: Vec<_> = (0..3) .map(|_| crate::state::checked_keypair_with_algorithm(Algorithm::BlsNormal)) .collect() };
    let mut live_keypairs = topology_keypairs.clone();
    live_keypairs.extend(manifest_keypairs.iter().cloned());
    seed_consensus_keys_with_pops(&state, &live_keypairs);
    install_lane_manifest_registry(
        &state,
        &[(lane_id, DataSpaceId::UNIVERSAL, manifest_validators.clone())],
    );
    {
        let mut topology = state.commit_topology.block();
        topology.clear();
        for keypair in &topology_keypairs {
            topology.push(PeerId::new(keypair.public_key().clone()));
        }
        topology.commit();
    }
    let pinned = repin_autoscale_lane_from_current_sources_for_test(&state, lane_id, height);
    let_row! { manifest_peers: BTreeSet<_> = manifest_validators .iter() .map(peer_id_for_account) .collect() };
    let committee = state
        .resolve_lane_committee_at_height(
            LaneAuthorityRoute::new(lane_id, DataSpaceId::UNIVERSAL),
            height,
        )
        .expect("creation-manifest autoscale pin must resolve")
        .into_validators();
    assert_eq!(committee, pinned);
    assert_eq!(
        committee.len(),
        4,
        "explicit autoscale authority must still satisfy the dataspace 3f+1 placement size"
    );
    assert!(
        committee.iter().all(|peer| manifest_peers.contains(peer)),
        "the creation-time manifest authority must be committed into the lane pin"
    );
    assert!(
        topology_keypairs
            .iter()
            .all(|keypair| !committee.contains(&PeerId::new(keypair.public_key().clone()))),
        "topology peers must not enter a sufficient creation-time manifest pin"
    );
}
