state_test! { sync da_pin_intents_kura_replay_rejects_future_created_autoscale_lane
    let temp_dir = tempfile::tempdir().expect("temp dir");
    let store_root = temp_dir.path().join("kura");
    let future_created_lane = LaneId::new(1);
    let_row! { elastic_lane = autoscale_elastic_lane_config(future_created_lane, DataSpaceId::UNIVERSAL, 7) };
    let_row! { catalog = LaneCatalog::new(nonzero!(2_u32), vec![LaneConfig::default(), elastic_lane]) .expect("future-created autoscale lane catalog") };
    let lane_config = RuntimeLaneConfig::from_catalog(&catalog);
    let kura_cfg = strict_kura_config_for_testing(store_root);
    let (kura, _) = Kura::open_test_kura_with_configured_lane_config(&kura_cfg, &lane_config).expect("init kura");
    let query_handle = LiveQueryStore::start_test();
    let state = State::new_for_testing(World::default(), Arc::clone(&kura), query_handle);
    {
        let mut nexus = state.nexus.write();
        nexus.autoscale.enabled = true;
        nexus.autoscale.min_lane_id = nonzero!(1_u32);
        nexus.autoscale.max_lane_id_exclusive = nonzero!(3_u32);
        nexus.lane_config = lane_config;
        nexus.lane_catalog = catalog;
    }
    let_row! { mut intent = test_da_pin_intent( *state.network_id_ref(), future_created_lane, 1, 0, StorageTicketId::new([0xA7; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0xB7; 32]), ) };
    set_test_da_pin_intent_alias(
        &mut intent,
        &ALICE_KEYPAIR,
        Some("future-replay-pin".to_owned()),
    );
    let bundle = DaPinIntentBundle::new(vec![intent.clone()]);
    let keypair = crate::state::checked_keypair();
    let_row! { new_block = BlockBuilder::new(vec![dummy_accepted_transaction()]) .chain(0, None) .with_da_pin_intents(Some(bundle)) .sign(keypair.private_key()) .unpack(|_| {}) };
    let signed_block: SignedBlock = new_block.into();
    assert!(signed_block.header().height().get() < 7);
    kura.store_block(crate::block::reserve_block_for_tests().initialize(signed_block.clone()))
        .expect("store future-created pin-intent block");
    let mut block_hashes = state.block_hashes.block();
    block_hashes.push(signed_block.hash());
    block_hashes.commit_for_tests();
    let store = state.da_pin_intents().expect("completed DA history read");
    assert!(
        store.get_by_alias("future-replay-pin").is_none(),
        "Kura replay must not hydrate pin intents before autoscale lane creation height"
    );
    assert_eq!(store.all_sorted().count(), 0);
}
