state_test! { sync confidential_compute_receipts_hydrate_from_kura
    use iroha_data_model::nexus::{NativeLaneManifestV1, NativeLaneMerkleCommitmentV1, NativeLanePrivacyCommitmentV1};
    let_row! { catalog = LaneCatalog::new( nonzero!(1_u32), vec![LaneConfig { id: LaneId::new(0), alias: "confidential-lane".to_string(), storage: LaneStorageProfile::SplitReplica, confidential_compute: Some(ConfidentialComputePolicy::new( ConfidentialComputeMechanism::Encryption, NonZeroU32::new(7).expect("non-zero key version"), BTreeSet::new(), )), ..LaneConfig::default() }], ) .expect("catalog") };
    let lane_config = RuntimeLaneConfig::from_catalog(&catalog);
    let kura_config = strict_kura_config_for_testing(PathBuf::new());
    let kura = Kura::new_temporary_with_configured_lane_catalog(
        &kura_config,
        &lane_config,
        &catalog,
    )
    .expect("configured confidential lane Kura");
    let constructor_world = World::default();
    let_row! { mut state = State::try_new(
constructor_world.sccp_committee_generations.allocation_budget().clone(), constructor_world,
        Arc::clone(&kura),
        LiveQueryStore::start_test(),
        #[cfg(feature = "telemetry")]
        <_>::default(),
    ).expect("empty configured State") };
    // Freeze the exact native source through the ordinary bounded loader before
    // this configured policy can enter a canonical State view.
    let lane = &catalog.lanes()[0];
    let source_directory = tempfile::tempdir().expect("isolated confidential manifest source");
    let source_path = source_directory.path().join(format!("{}.manifest.json", lane.alias));
    let source = NativeLaneManifestV1 {
        version: Some(NativeLaneManifestV1::VERSION),
        lane: Some(lane.alias.clone()),
        governance: lane.governance.clone(),
        privacy_commitments: Some(vec![NativeLanePrivacyCommitmentV1 {
            id: Some(7),
            scheme: Some("merkle".to_owned()),
            merkle: Some(NativeLaneMerkleCommitmentV1 {
                root: Some(hex::encode([0xA5; 32])),
                max_depth: Some(12),
            }),
        }]),
        ..Default::default()
    };
    std::fs::write(&source_path, norito::json::to_vec(&source).unwrap())
        .expect("write exact confidential manifest");
    let governance = iroha_config::parameters::actual::GovernanceCatalog::default();
    let manifests = Arc::new(LaneManifestRegistry::from_config(
        &catalog,
        &governance,
        &iroha_config::parameters::actual::LaneRegistry {
            manifest_directory: Some(source_directory.path().to_path_buf()),
            ..Default::default()
        },
    ));
    source_directory.close().expect("remove retained frozen source files");
    assert!(!source_path.exists());
    manifests.validate_materialized_authority_for_catalog(&catalog, &governance)
        .expect("exact privacy policy retains its original materialized source");
    manifests.validate_active_coverage_for_catalog(&catalog)
        .expect("exact confidential lane privacy coverage");
    state.install_lane_manifests_for_testing(&manifests);
    state.install_pre_genesis_nexus_for_testing(iroha_config::parameters::actual::Nexus {
        lane_catalog: catalog.clone(),
        lane_config,
        ..Default::default()
    });
    state.configure_test_runtime_defaults();
    assert_eq!(state.nexus_snapshot().lane_catalog, catalog);
    assert_eq!(
        state.nexus_snapshot().lane_config.entry(LaneId::SINGLE)
            .and_then(|entry| entry.confidential_compute.as_ref())
            .map(|policy| policy.key_version.get()),
        Some(7),
        "hydration reads the actual canonical confidential policy"
    );
    let_row! { record = iroha_data_model::da::commitment::DaCommitmentRecord::new( LaneId::new(0), 1, 0, BlobDigest::new([0xAA; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0xBB; 32]), DaProofScheme::MerkleSha256, Hash::prehashed([0xCC; 32]), None, RetentionClass::default(), StorageTicketId::new([0xEE; 32]), checked_da_ack_signature(0x11), ) };
    let bundle = DaCommitmentBundle::new(vec![record.clone()]);
    let keypair = crate::state::checked_keypair();
    let_row! { signed_block: SignedBlock = BlockBuilder::new(Vec::new()) .chain(0, None) .with_da_commitments(Some(bundle)) .sign(keypair.private_key()) .unpack(|_| {}) .into() };
    kura.store_block(crate::block::reserve_block_for_tests().initialize(signed_block.clone()))
        .expect("store block");
    let mut block_hashes = state.block_hashes.block();
    block_hashes.push(signed_block.hash());
    block_hashes.commit_for_tests();
    state
        .ensure_da_indexes_hydrated()
        .expect("hydrate from kura should succeed");
    let receipts = state.da_confidential_compute().expect("completed DA history read");
    let_row! { stored = receipts .get_by_lane_epoch_sequence(0, 1, 0) .expect("receipt present") };
    assert_eq!(stored.receipt.key_version.get(), 7);
    assert_eq!(
        stored.receipt.storage_ticket,
        StorageTicketId::new([0xEE; 32])
    );
}
state_test! { sync da_pin_intents_replay_sanitizes_invalid_entries
    strict_single_lane_kura_fixture!(temp_dir, catalog, lane_config, kura);
    let query_handle = LiveQueryStore::start_test();
    let state = State::new_for_testing(World::default(), Arc::clone(&kura), query_handle);
    let lane = lane_config.primary().lane_id;
    let_row! { mut superseded = test_da_pin_intent( *state.network_id_ref(), lane, 1, 1, StorageTicketId::new([0x01; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0x01; 32]), ) };
    set_test_da_pin_intent_alias(
        &mut superseded,
        &ALICE_KEYPAIR,
        Some("alias-one".to_owned()),
    );
    let_row! { mut winner = test_da_pin_intent( *state.network_id_ref(), lane, 2, 0, StorageTicketId::new([0x02; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0x02; 32]), ) };
    set_test_da_pin_intent_alias(
        &mut winner,
        &ALICE_KEYPAIR,
        Some("alias-one".to_owned()),
    );
    let_row! { mut zero_manifest = test_da_pin_intent( *state.network_id_ref(), lane, 3, 0, StorageTicketId::new([0x03; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0; 32]), ) };
    set_test_da_pin_intent_alias(
        &mut zero_manifest,
        &ALICE_KEYPAIR,
        Some("alias-drop".to_owned()),
    );
    let_row! { plain = test_da_pin_intent( *state.network_id_ref(), lane, 4, 0, StorageTicketId::new([0x04; 32]), iroha_data_model::sorafs::pin_registry::ManifestDigest::new([0x04; 32]), ) };
    let_row! { bundle = DaPinIntentBundle::new(vec![ superseded.clone(), winner.clone(), zero_manifest, plain.clone(), ]) };
    let keypair = crate::state::checked_keypair();
    let_row! { new_block = BlockBuilder::new(vec![dummy_accepted_transaction()]) .chain(0, None) .with_da_pin_intents(Some(bundle)) .sign(keypair.private_key()) .unpack(|_| {}) };
    let signed_block: SignedBlock = new_block.into();
    kura.store_block(crate::block::reserve_block_for_tests().initialize(signed_block.clone()))
        .expect("store block");
    let mut block_hashes = state.block_hashes.block();
    block_hashes.push(signed_block.hash());
    block_hashes.commit_for_tests();
    state.rewind_da_indexes_to_height(signed_block.header().height().get())
        .expect("replay pin sanitizer from the exact committed Kura prefix");
    let store = state.da_pin_intents().expect("completed DA history read");
    let collected: Vec<_> = store.all_sorted().cloned().collect();
    drop(store);
    assert_eq!(collected.len(), 2);
    assert!(
        collected
            .iter()
            .any(|intent| intent.intent.storage_ticket == winner.storage_ticket)
    );
    assert!(
        collected
            .iter()
            .any(|intent| intent.intent.storage_ticket == plain.storage_ticket)
    );
    assert_eq!(
        state
            .da_pin_intents().expect("completed DA history read")
            .get_by_alias("alias-one")
            .map(|(ticket, _)| ticket),
        Some(&winner.storage_ticket)
    );
}
