state_test! { sync axt_policy_snapshot_ignores_zero_manifest_hash_sentinel
    let uaid = UniversalAccountId::from_hash(Hash::new(b"uaid::zero-manifest-snapshot"));
    let dataspace = DataSpaceId::new(21);
    let lane_id = LaneId::new(5);
    let_row! { lane_catalog = LaneCatalog::new( nonzero!(6_u32), vec![public_lane!(lane_id, dataspace, "lane5".into())], ) .expect("lane catalog") };
    let domain_id: DomainId = DomainId::try_new("zero-snapshot", "universal").expect("domain id");
    let keypair = crate::state::checked_keypair();
    let account_id = AccountId::new(keypair.public_key().clone());
    let_row! { account = new_account_in_domain(&account_id, &domain_id) .with_uaid(Some(uaid)) .build(&account_id) };
    let domain = Domain::new(domain_id).build(&account_id);
    let world = World::with([domain], [account], []);
    let_row! { manifest = AssetPermissionManifest { version: ManifestVersion::default(), uaid, dataspace, issued_ms: 0, activation_epoch: 1, expiry_epoch: Some(4), entries: Vec::new(), } };
    let mut record = SpaceDirectoryManifestRecord::new(manifest);
    record.lifecycle.mark_activated(1);
    record.manifest_hash = Hash::prehashed([0; Hash::LENGTH]);
    let digest = record.manifest_hash.as_ref();
    assert!(
        digest[..Hash::LENGTH - 1].iter().all(|byte| *byte == 0) && digest[Hash::LENGTH - 1] == 1,
        "test setup must install a zeroed manifest hash sentinel"
    );
    let mut set = SpaceDirectoryManifestSet::default();
    set.upsert(record);
    let kura = Kura::blank_kura_for_testing();
    let query_handle = LiveQueryStore::start_test();
    let mut state = State::new_for_testing(world, kura, query_handle);
    state
        .world
        .space_directory_manifests_mut_for_testing()
        .insert(uaid, set);
    {
        let nexus = state.nexus.get_mut();
        install_test_nexus_lane_catalog(nexus, lane_catalog);
    }
    let snapshot = CoreHost::axt_policy_snapshot_from_state(&state.view());
    assert!(snapshot.is_none(), "sentinel manifests must be ignored");
}
state_test! { sync axt_policy_snapshot_ignores_stale_geometry_for_removed_catalog_lane
    let uaid = UniversalAccountId::from_hash(Hash::new(b"uaid::stale-axt-snapshot"));
    let dataspace = DataSpaceId::new(22);
    let stale_lane = LaneId::new(5);
    let_row! { authoritative_catalog = LaneCatalog::new( nonzero!(1_u32), vec![LaneConfig { id: LaneId::SINGLE, dataspace_id: DataSpaceId::UNIVERSAL, alias: "public".into(), ..LaneConfig::default() }], ) .expect("authoritative lane catalog") };
    let_row! { stale_geometry_catalog = LaneCatalog::new( nonzero!(6_u32), vec![public_lane!(stale_lane, dataspace, "stale-axt".into())], ) .expect("stale lane geometry") };
    let domain_id: DomainId = DomainId::try_new("stale-axt", "universal").expect("domain id");
    uaid_account_world_fixture!(domain_id, uaid, keypair, account_id, world);
    activated_manifest_record!(record, uaid, dataspace);
    insert_space_directory_manifest!(world, uaid, record, set);
    let kura = Kura::blank_kura_for_testing();
    let query_handle = LiveQueryStore::start_test();
    let mut state = State::new_for_testing(world, kura, query_handle);
    {
        let nexus = state.nexus.get_mut();
        install_test_nexus_lane_catalog(nexus, authoritative_catalog);
        nexus.dataspace_catalog = DataSpaceCatalog::new(vec![
            DataSpaceMetadata {
                id: DataSpaceId::UNIVERSAL,
                alias: "universal".to_owned(),
                description: None,
                fault_tolerance: 1,
            },
            DataSpaceMetadata {
                id: dataspace,
                alias: "stale-axt".to_owned(),
                description: None,
                fault_tolerance: 1,
            },
        ])
        .expect("dataspace catalog containing stale lane dataspace");
        nexus.lane_config = RuntimeLaneConfig::from_catalog(&stale_geometry_catalog);
        assert!(
            nexus.lane_config.entry(stale_lane).is_some(),
            "test must seed derived geometry for the removed lane"
        );
        assert!(
            nexus
                .lane_catalog
                .lanes()
                .iter()
                .all(|lane| lane.id != stale_lane),
            "test must keep stale lane out of the authoritative catalog"
        );
    }
    let snapshot = CoreHost::axt_policy_snapshot_from_state(&state.view());
    assert!(
        snapshot.is_none(),
        "stale geometry-only lanes must not produce AXT policy entries"
    );
    assert!(
        state.world.axt_policies.view().get(&dataspace).is_none(),
        "stale geometry-only lanes must not populate cached AXT policy state"
    );
}
