state_test! { sync block_releases_expired_governance_lock_through_stored_custody_after_config_change
    let domain_id = DomainId::try_new("governance", "custody").expect("domain id");
    let_row! { old_definition_id = AssetDefinitionId::derive_from_components( domain_id.clone(), "old_vote".parse().expect("asset name"), ) };
    let_row! { live_definition_id = AssetDefinitionId::derive_from_components( domain_id.clone(), "live_vote".parse().expect("asset name"), ) };
    let old_escrow = (*BOB_ID).clone();
    let live_escrow = AccountId::new(checked_keypair().public_key().clone());
    let voter = (*ALICE_ID).clone();
    let old_escrow_asset_id = AssetId::new(old_definition_id.clone(), old_escrow.clone());
    let voter_asset_id = AssetId::new(old_definition_id.clone(), voter.clone());
    let live_escrow_asset_id = AssetId::new(live_definition_id.clone(), live_escrow.clone());
    let_row! { world = World::with_assets( [Domain::new(domain_id.clone()).build(&voter)], [ Account::new(voter.clone()).build(&voter), Account::new(old_escrow.clone()).build(&voter), Account::new(live_escrow.clone()).build(&voter), ], [ AssetDefinition::numeric( old_definition_id.clone(), "old_vote", iroha_data_model::asset::AssetBalancePolicy::Global, Some(domain_id.clone()), ) .build(&voter), AssetDefinition::numeric( live_definition_id.clone(), "live_vote", iroha_data_model::asset::AssetBalancePolicy::Global, Some(domain_id), ) .build(&voter), ], [ Asset::new(old_escrow_asset_id.clone(), Quantity::from(42_u32)), Asset::new(live_escrow_asset_id.clone(), Quantity::from(7_u32)), ], [], ) };
    let kura = Kura::blank_kura_for_testing();
    let query = LiveQueryStore::start_test();
    let mut state = State::new_for_testing(world, kura, query);
    let mut live_governance = state.gov.clone();
    live_governance.voting_asset_id = live_definition_id;
    live_governance.bond_escrow_account = live_escrow.clone();
    state.set_gov(live_governance);
    let referendum_id = "stored-custody-release".to_owned();
    {
        let mut world_block = state.world.block();
        let mut locks = GovernanceLocksForReferendum::default();
        locks.locks.insert(
            voter.clone(),
            GovernanceLockRecord {
                owner: voter.clone(),
                amount: Quantity::from(42_u32),
                slashed: Quantity::zero(),
                expiry_height: 5,
                direction: 0,
                duration_blocks: 0,
                custody: GovernanceLockCustody {
                    escrowed: true,
                    asset_definition_id: old_definition_id,
                    bond_escrow_account: old_escrow,
                    slash_receiver_account: live_escrow,
                },
            },
        );
        world_block.put_governance_locks(referendum_id.clone(), locks);
        *world_block.governance_last_unlock_sweep_height.get_mut() = 1;
        world_block.commit();
    }
    let header = BlockHeader::new(nonzero!(10_u64), None, None, 0, 0);
    let block = state.block(header);
    assert!(
        block.world.assets.get(&old_escrow_asset_id).is_none(),
        "stored escrow must be debited and its zero balance removed"
    );
    assert_eq!(
        block
            .world
            .assets
            .get(&voter_asset_id)
            .map(|value| value.as_ref().clone()),
        Some(Quantity::from(42_u32)),
        "stored custody asset must return to the lock owner"
    );
    assert_eq!(
        block
            .world
            .assets
            .get(&live_escrow_asset_id)
            .map(|value| value.as_ref().clone()),
        Some(Quantity::from(7_u32)),
        "changed live governance custody must remain untouched"
    );
    assert!(
        block.world.governance_locks.get(&referendum_id).is_none(),
        "successfully released empty lock containers must be removed"
    );
    assert_eq!(
        *block.world.governance_last_unlock_sweep_height.get(), 10,
        "fully successful stored-custody release must advance the sweep marker"
    );
}
