const STATE_QUERY_PHYSICAL_FAMILIES: [crate::kura::resource_inventory::Family; 6] = {
    use crate::kura::resource_inventory::Family;
    [
        Family::CanonicalIndex,
        Family::CanonicalHashes,
        Family::PipelineIndex,
        Family::QueryMarkerRecords,
        Family::EvidenceKeyRecords,
        Family::StorageBytes,
    ]
};

#[test]
fn query_journal_checks_cover_every_current_physical_inventory_owner() {
    use crate::kura::resource_inventory::{ALL_FAMILIES, Family};
    assert_eq!(
        &ALL_FAMILIES[..Family::CanonicalIndex as usize],
        &[
            Family::ResidentCanonical,
            Family::ResidentTransaction,
            Family::ResidentFrontier,
            Family::ResidentQueue,
        ]
    );
    assert_eq!(
        &ALL_FAMILIES[Family::CanonicalIndex as usize..],
        &STATE_QUERY_PHYSICAL_FAMILIES
    );
}

// Check every component individually; this never qualifies a complete resident snapshot.
fn assert_state_query_physical_families_available(kura: &Kura) {
    let mut checked = 0;
    for family in STATE_QUERY_PHYSICAL_FAMILIES {
        kura.resource_inventory_component_for_tests(family)
            .unwrap_or_else(|error| {
                panic!("valid physical baseline required for {family:?}: {error:?}")
            });
        checked += 1;
    }
    assert_eq!(
        checked, 6,
        "the entire fixed physical-family baseline is required"
    );
}

fn assert_state_query_physical_families_unavailable(kura: &Kura) {
    for family in STATE_QUERY_PHYSICAL_FAMILIES {
        assert!(
            kura.resource_inventory_component_for_tests(family).is_err(),
            "failed query recovery cannot publish {family:?}"
        );
    }
}

state_test! { sync query_resource_inventory_tracks_real_marker_replacement_bytes
    use crate::kura::resource_inventory::Family;
    let temp_dir = tempfile::tempdir().expect("temporary journal root");
    let kura = state_journal_test_kura(&temp_dir.path().join("kura"));
    let state = State::new_for_testing(World::default(), Arc::clone(&kura), LiveQueryStore::start_test());
    let empty = kura.resource_inventory_component_for_tests(Family::QueryMarkerRecords)
        .expect("initialized empty marker family");
    assert_eq!(empty.persisted_entries, 0);
    assert_eq!(empty.index_bytes, 0);
    for (seed, shards) in [(1, 1), (2, 5), (3, 0), (4, 2)] {
        state.persist_query_index_status(u64::from(seed), None);
        state.persist_query_projection_checkpoint(Some(state_journal_test_projection_checkpoint(seed, shards)));
        let index_path = state.query_index_journal_path();
        let projection_path = state.query_projection_checkpoint_journal_path();
        let actual_bytes = std::fs::metadata(&index_path).expect("index metadata").len()
            .checked_add(std::fs::metadata(&projection_path).expect("projection metadata").len())
            .expect("bounded journal byte sum");
        let measured = kura.resource_inventory_component_for_tests(Family::QueryMarkerRecords)
            .expect("completed marker publication");
        assert_eq!(measured.persisted_entries, 2);
        assert_eq!(measured.index_bytes, actual_bytes);
        assert_eq!(measured.temporary_index_bytes, 0);
        assert_eq!(measured.resident_associations, 0);
        assert!(!index_path.with_extension("norito.tmp").exists());
        assert!(!projection_path.with_extension("norito.tmp").exists());
    }
}

state_test! { sync query_resource_inventory_recovers_both_main_temp_pairs_without_undercounting
    use crate::kura::resource_inventory::Family;
    let temp_dir = tempfile::tempdir().expect("temporary journal root");
    let root = temp_dir.path().join("kura");
    let seeded = state_journal_test_kura(&root);
    let expected = seed_distinct_state_journal_main_and_temp_files(&seeded);
    drop(seeded);
    // Crash fixtures are inventoried by the real opener before State recovers them.
    let kura = state_journal_test_kura(&root);
    let before = kura.resource_inventory_component_for_tests(Family::QueryMarkerRecords)
        .expect("four physical marker records");
    assert_eq!(before.persisted_entries, 4);
    assert!(before.index_bytes > 0);
    assert!(before.temporary_index_bytes > 0);
    let state = State::new_for_testing(World::default(), Arc::clone(&kura), LiveQueryStore::start_test());
    assert_eq!(state.query_index_status_snapshot(), expected.query_index);
    assert_eq!(state.query_projection_checkpoint_snapshot(), Some(expected.projection));
    let expected_bytes = [state.query_index_journal_path(), state.query_projection_checkpoint_journal_path()]
        .iter().map(|path| std::fs::metadata(path).expect("recovered marker metadata").len()).sum::<u64>();
    let after = kura.resource_inventory_component_for_tests(Family::QueryMarkerRecords)
        .expect("fully recovered marker family");
    assert_eq!(after.persisted_entries, 2);
    assert_eq!(after.index_bytes, expected_bytes);
    assert_eq!(after.temporary_index_bytes, 0);
    let usage = kura.disk_usage_accounting_snapshot_for_tests().expect("raw disk accounting");
    assert!(usage.enforced_initialized && usage.total_initialized);
    assert_eq!(usage.cached_enforced_bytes, usage.exact_enforced_bytes);
    assert_eq!(usage.cached_total_bytes, usage.exact_total_bytes);
}

state_test! { sync failed_query_journal_publication_keeps_resource_inventory_unavailable
    use crate::kura::resource_inventory::Family;
    for projection in [false, true] {
        let temp_dir = tempfile::tempdir().expect("temporary journal root");
        let kura = state_journal_test_kura(&temp_dir.path().join("kura"));
        let state = State::new_for_testing(World::default(), Arc::clone(&kura), LiveQueryStore::start_test());
        let path = if projection { state.query_projection_checkpoint_journal_path() } else { state.query_index_journal_path() };
        let temporary = path.with_extension("norito.tmp");
        assert_state_query_physical_families_available(&kura);
        assert_eq!(kura.resource_inventory_component_for_tests(Family::QueryMarkerRecords)
            .expect("valid empty marker baseline").persisted_entries, 0);
        std::fs::create_dir(&temporary).expect("inject blocked temporary-file publication");
        if projection {
            state.persist_query_projection_checkpoint(Some(state_journal_test_projection_checkpoint(1, 1)));
        } else {
            state.persist_query_index_status(1, None);
        }
        assert!(!path.exists());
        assert!(temporary.is_dir());
        assert!(kura.resource_inventory_component_for_tests(Family::QueryMarkerRecords).is_err());
        std::fs::remove_dir(&temporary).expect("remove injected publication obstruction");
        kura.refresh_disk_usage_bytes().expect("refresh physical disk bytes");
        assert!(kura.resource_inventory_component_for_tests(Family::QueryMarkerRecords).is_err(),
            "a disk byte rescan cannot authenticate an interrupted marker inventory");
    }
}

state_test! { sync corrupt_query_journal_load_cannot_publish_a_complete_resource_inventory
    use crate::kura::resource_inventory::Family;
    for projection in [false, true] {
        let temp_dir = tempfile::tempdir().expect("temporary journal root");
        let root = temp_dir.path().join("kura");
        drop(state_journal_test_kura(&root));
        let path = if projection { QueryProjectionCheckpointJournal::journal_path(&root) } else { QueryIndexJournal::journal_path(&root) };
        let damaged = b"bounded malformed marker";
        std::fs::write(&path, damaged).expect("write malformed crash fixture");
        let kura = state_journal_test_kura(&root);
        assert_state_query_physical_families_available(&kura);
        let before = kura.resource_inventory_component_for_tests(Family::QueryMarkerRecords)
            .expect("bounded malformed record remains physically measurable before decode");
        assert_eq!(before.persisted_entries, 1);
        assert_eq!(before.index_bytes, u64::try_from(damaged.len()).expect("bounded damaged marker"));
        let state = State::new_for_testing(World::default(), Arc::clone(&kura), LiveQueryStore::start_test());
        assert!(kura.resource_inventory_component_for_tests(Family::QueryMarkerRecords).is_err());
        assert_eq!(std::fs::read(&path).expect("retained malformed marker"), damaged);
        if projection {
            assert!(state.query_projection_checkpoint_snapshot().is_none());
        } else {
            assert_eq!(state.query_index_status_snapshot().indexed_height, 0);
        }
    }
}

state_test! { sync query_recovery_promotion_failures_never_publish_measurable_physical_inventory
    use crate::query::{index_status, projection_checkpoint_journal};
    assert_eq!(index_status::PROMOTION_FAILURES.len(), projection_checkpoint_journal::PROMOTION_FAILURES.len());
    for projection in [false, true] {
        for case in 0..index_status::PROMOTION_FAILURES.len() {
            let temp_dir = tempfile::tempdir().expect("promotion failure journal root");
            let root = temp_dir.path().join("kura");
            let seeded = state_journal_test_kura(&root);
            seed_distinct_state_journal_main_and_temp_files(&seeded);
            let path = if projection { QueryProjectionCheckpointJournal::journal_path(&root) }
                else { QueryIndexJournal::journal_path(&root) };
            let temporary = path.with_extension("norito.tmp");
            let original = std::fs::read(&path).expect("valid original marker");
            let recovered = std::fs::read(&temporary).expect("valid staged marker");
            if case == 0 { std::fs::remove_file(&path).expect("initial rename has no fallback destination"); }
            drop(seeded);
            let kura = state_journal_test_kura(&root);
            assert_state_query_physical_families_available(&kura);
            if projection {
                QueryProjectionCheckpointJournal::fail_next_promotion_for_tests(
                    projection_checkpoint_journal::PROMOTION_FAILURES[case]);
            } else {
                QueryIndexJournal::fail_next_promotion_for_tests(index_status::PROMOTION_FAILURES[case]);
            }
            let state = State::new_for_testing(World::default(), Arc::clone(&kura), LiveQueryStore::start_test());
            assert_state_query_physical_families_unavailable(&kura);
            if projection {
                assert!(!QueryProjectionCheckpointJournal::promotion_failure_pending_for_tests());
                assert!(state.query_projection_checkpoint_snapshot().is_none());
            } else {
                assert!(!QueryIndexJournal::promotion_failure_pending_for_tests());
                assert_eq!(state.query_index_status_snapshot().indexed_height, 0);
            }
            match case {
                0 | 2 => {
                    assert!(!path.exists());
                    assert_eq!(std::fs::read(&temporary).expect("retained recovery marker"), recovered);
                }
                1 => {
                    assert_eq!(std::fs::read(&path).expect("original marker not removed"), original);
                    assert_eq!(std::fs::read(&temporary).expect("retained recovery marker"), recovered);
                }
                3 | 4 => {
                    assert_eq!(std::fs::read(&path).expect("renamed marker awaiting directory durability"), recovered);
                    assert!(!temporary.exists());
                }
                _ => unreachable!("closed promotion failure cases"),
            }
            kura.refresh_disk_usage_bytes().expect("measurable residue can be rescanned");
            assert_state_query_physical_families_unavailable(&kura);
        }
    }
}

#[test]
fn lane_storage_identity_projects_one_exact_canonical_runtime_image() {
    let state = State::new_for_testing(
        World::default(),
        Kura::blank_kura_for_testing(),
        LiveQueryStore::start_test(),
    );
    let identity = state
        .lane_storage_identity(LaneId::SINGLE)
        .expect("active primary identity");
    let runtime = state.canonical_runtime.view();
    let lane = runtime
        .lanes
        .iter()
        .find(|lane| lane.id == LaneId::SINGLE)
        .unwrap();
    let lineage = runtime
        .lane_incarnation_lineage
        .iter()
        .find(|entry| entry.lane_id == LaneId::SINGLE)
        .unwrap();
    assert_eq!(identity.network_id, state.network_id);
    assert_eq!(identity.lane_id, lane.id);
    assert_eq!(identity.dataspace_id, lane.dataspace_id);
    assert_eq!(identity.incarnation, lineage.incarnation);
    assert_eq!(identity.activation_height, lineage.activation_height);
    assert!(state.lane_storage_identity(LaneId::new(u32::MAX)).is_none());
    assert!(
        identity
            .blocks_dir("root")
            .starts_with("root/blocks/instances")
    );
}

#[test]
fn frozen_plain_projection_rejects_malformed_corpus_and_restores_slashed_positions() {
    use iroha_data_model::governance::conviction::{PlainVotingContextV1, PlainVotingResultV1};
    use iroha_data_model::isi::error::{InstructionExecutionError, InvalidParameterError};
    let mut referendum = indexed_plain_referendum();
    let PlainVotingContextV1::Conviction(policy) = &mut referendum.plain_context else {
        unreachable!()
    };
    policy.minimum_bond = 10_u64.into();
    policy.bond_escrow_account = iroha_test_samples::CARPENTER_ID.clone();
    policy.slash_receiver_account = iroha_test_samples::SAMPLE_GENESIS_ACCOUNT_ID.clone();
    let mut lock = indexed_governance_lock(ALICE_ID.clone(), 10);
    lock.custody.bond_escrow_account = policy.bond_escrow_account.clone();
    lock.custody.slash_receiver_account = policy.slash_receiver_account.clone();
    lock.amount = 4_u64.into();
    lock.slashed = 6_u64.into();
    let mut world = World::new();
    world
        .governance_referenda
        .insert("slash-restore".into(), referendum.clone());
    for (remaining, slashed) in [(4_u64, 6_u64), (0, 10)] {
        lock.amount = remaining.into();
        lock.slashed = slashed.into();
        lock.validate_plain_context(referendum.plain_policy().unwrap())
            .expect("the original bond still meets the positive frozen minimum");
        let locks = GovernanceLocksForReferendum {
            locks: BTreeMap::from([(ALICE_ID.clone(), lock.clone())]),
        };
        world
            .governance_locks
            .insert("slash-restore".into(), locks.clone());
        world
            .rebuild_governance_read_indexes()
            .expect("majority/full slash retains valid original bond");
        world.validate_plain_governance_tally_capacity().unwrap();
        assert!(plain_governance_tally(&referendum, Some(&locks), 1).is_ok());
    }
    let mut wrong_owner = GovernanceLocksForReferendum {
        locks: BTreeMap::from([(BOB_ID.clone(), lock.clone())]),
    };
    let owner_error = crate::smartcontracts::isi::world::isi::plain_governance_tally_v1(
        &wrong_owner,
        None,
        Some(1),
        referendum.plain_policy().unwrap(),
    )
    .unwrap_err();
    assert!(
        matches!(
            &owner_error,
            InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(message))
                if message == "plain lock owner does not match its corpus key"
        ),
        "unexpected corpus rejection: {owner_error:?}"
    );
    assert_eq!(
        plain_governance_tally(&referendum, Some(&wrong_owner), 1).unwrap_err(),
        owner_error.to_string()
    );
    wrong_owner.locks.clear();
    lock.direction = 3;
    wrong_owner.locks.insert(ALICE_ID.clone(), lock.clone());
    assert!(
        plain_governance_tally(&referendum, Some(&wrong_owner), 1)
            .unwrap_err()
            .contains("direction")
    );
    for field in ["slashed", "duration_blocks"] {
        let mut json = norito::json::to_value(&lock).unwrap();
        json.as_object_mut().unwrap().remove(field);
        assert!(
            norito::json::from_value::<GovernanceLockRecord>(json).is_err(),
            "missing {field} has no V1 layout"
        );
    }
    let mut closed = referendum;
    let PlainVotingContextV1::Conviction(policy) = &closed.plain_context else {
        unreachable!()
    };
    closed.plain_result = PlainVotingResultV1::Decided(policy.decide([4, 2, 1]).unwrap());
    closed.status = GovernanceReferendumStatus::Closed;
    world.governance_locks = mv::storage::Storage::default();
    world
        .governance_referenda
        .insert("slash-restore".into(), closed.clone());
    world
        .rebuild_governance_read_indexes()
        .expect("closed result remains after all locks released");
    assert_eq!(
        plain_governance_tally(&closed, None, 999).unwrap(),
        [4, 2, 1]
    );
    closed.plain_result = PlainVotingResultV1::Pending;
    world
        .governance_referenda
        .insert("slash-restore".into(), closed);
    assert!(
        world
            .rebuild_governance_read_indexes()
            .unwrap_err()
            .contains("context/result")
    );
}

#[test]
fn frozen_plain_minimum_bond_is_enforced_by_validator_tally_and_restore() {
    use iroha_data_model::governance::conviction::{PlainVotingContextV1, PlainVotingResultV1};
    use iroha_data_model::isi::error::{InstructionExecutionError, InvalidParameterError};

    const BELOW_MINIMUM: &str = "original public conviction bond is below its frozen minimum";
    let referendum_id = "minimum-bond-restore";
    let mut referendum = indexed_plain_referendum();
    let PlainVotingContextV1::Conviction(policy) = &mut referendum.plain_context else {
        unreachable!()
    };
    policy.minimum_bond = 10_u64.into();
    policy.bond_escrow_account = iroha_test_samples::CARPENTER_ID.clone();
    policy.slash_receiver_account = iroha_test_samples::SAMPLE_GENESIS_ACCOUNT_ID.clone();
    let mut valid_lock = indexed_governance_lock(ALICE_ID.clone(), 10);
    valid_lock.amount = 10_u64.into();
    valid_lock.custody.bond_escrow_account = policy.bond_escrow_account.clone();
    valid_lock.custody.slash_receiver_account = policy.slash_receiver_account.clone();
    valid_lock.validate_plain_context(policy).unwrap();
    let mut locks = GovernanceLocksForReferendum {
        locks: BTreeMap::from([(ALICE_ID.clone(), valid_lock.clone())]),
    };
    assert!(plain_governance_tally(&referendum, Some(&locks), 1).is_ok());
    let mut world = World::new();
    world
        .governance_referenda
        .insert(referendum_id.into(), referendum.clone());
    world
        .governance_locks
        .insert(referendum_id.into(), locks.clone());
    world
        .rebuild_governance_read_indexes()
        .expect("exact-minimum baseline is valid");

    for (remaining, slashed) in [(9_u64, 0_u64), (4, 5), (0, 9)] {
        let mut lock = valid_lock.clone();
        lock.amount = remaining.into();
        lock.slashed = slashed.into();
        assert_eq!(
            lock.validate_plain_context(referendum.plain_policy().unwrap())
                .unwrap_err(),
            BELOW_MINIMUM
        );
        locks.locks.insert(ALICE_ID.clone(), lock);
        let tally_error = crate::smartcontracts::isi::world::isi::plain_governance_tally_v1(
            &locks,
            None,
            Some(1),
            referendum.plain_policy().unwrap(),
        )
        .unwrap_err();
        assert!(
            matches!(
                &tally_error,
                InstructionExecutionError::InvalidParameter(InvalidParameterError::SmartContract(message))
                    if message == BELOW_MINIMUM
            ),
            "unexpected original-bond rejection: {tally_error:?}"
        );
        assert_eq!(
            plain_governance_tally(&referendum, Some(&locks), 1).unwrap_err(),
            tally_error.to_string()
        );
        world
            .governance_locks
            .insert(referendum_id.into(), locks.clone());
        assert_eq!(
            world.rebuild_governance_read_indexes().unwrap_err(),
            BELOW_MINIMUM
        );
    }

    // A retained decision does not depend on current locks, but restore must still reject
    // an impossible retained position instead of installing it into the expiry index.
    let mut closed = referendum.clone();
    closed.plain_result =
        PlainVotingResultV1::Decided(closed.plain_policy().unwrap().decide([4, 2, 1]).unwrap());
    closed.status = GovernanceReferendumStatus::Closed;
    world
        .governance_referenda
        .insert(referendum_id.into(), closed.clone());
    assert_eq!(
        plain_governance_tally(&closed, Some(&locks), 999).unwrap(),
        [4, 2, 1]
    );
    assert_eq!(
        world.rebuild_governance_read_indexes().unwrap_err(),
        BELOW_MINIMUM
    );
    assert_eq!(
        world
            .governance_referenda
            .view()
            .get(referendum_id)
            .unwrap()
            .plain_result,
        closed.plain_result
    );

    // Zero units are a valid zero-weight position only under an explicit zero minimum.
    let PlainVotingContextV1::Conviction(policy) = &mut referendum.plain_context else {
        unreachable!()
    };
    policy.minimum_bond = Quantity::zero();
    valid_lock.amount = Quantity::zero();
    valid_lock.validate_plain_context(policy).unwrap();
    locks.locks.insert(ALICE_ID.clone(), valid_lock);
    assert_eq!(
        plain_governance_tally(&referendum, Some(&locks), 1).unwrap(),
        [0; 3]
    );
    world
        .governance_referenda
        .insert(referendum_id.into(), referendum);
    world.governance_locks.insert(referendum_id.into(), locks);
    world
        .rebuild_governance_read_indexes()
        .expect("explicit zero-minimum zero-position is valid");
}

