#[test]
fn sccp_derived_indexes_bind_inserted_keys_and_deletions_in_merge_write_sets() {
    use iroha_data_model::bridge::SccpNetworkV1;
    let world = World::new();
    let fields = [
        "sccp_destination_pending_generations",
        "sccp_reconciliation_due",
    ];
    for (index, field) in fields.iter().enumerate() {
        let mut inserted = Vec::new();
        for key in [7, 8] {
            let mut block = world.block();
            assert!(block.sccp_execution_write_set_bytes().is_empty());
            let before = block.merge_execution_write_set_bytes();
            if index == 0 {
                block.sccp_destination_pending_generations.insert(key, ());
            } else {
                block
                    .sccp_reconciliation_due
                    .try_insert_admitted((key, SccpNetworkV1::EthereumMainnet, 1), ())
                    .unwrap();
            }
            let delta = block.sccp_execution_write_set_bytes();
            assert!(
                delta
                    .windows(field.len())
                    .any(|bytes| bytes == field.as_bytes()),
                "every changed SCCP index must appear in its canonical delta"
            );
            let mut streamed = Vec::new();
            block.write_sccp_execution_delta(&mut streamed).unwrap();
            assert_eq!(streamed, delta);
            let merge = block.merge_execution_write_set_bytes();
            assert_ne!(
                merge, before,
                "a derived index change must affect merge certification"
            );
            assert!(merge.ends_with(&delta));
            inserted.push(delta);
            drop(block);
            assert!(world.sccp_destination_pending_generations.view().is_empty());
            assert!(world.sccp_reconciliation_due.view().is_empty());
        }
        assert_ne!(
            inserted[0], inserted[1],
            "equal unit values cannot hide different keys"
        );
    }
    {
        let mut seed = world.block();
        seed.sccp_destination_pending_generations.insert(7, ());
        seed.sccp_reconciliation_due
            .try_insert_admitted((7, SccpNetworkV1::EthereumMainnet, 1), ())
            .unwrap();
        seed.commit();
    }
    for (index, field) in fields.iter().enumerate() {
        let mut block = world.block();
        assert!(block.sccp_execution_write_set_bytes().is_empty());
        let before = block.merge_execution_write_set_bytes();
        if index == 0 {
            block.sccp_destination_pending_generations.remove(7);
        } else {
            block
                .sccp_reconciliation_due
                .try_remove_admitted((7, SccpNetworkV1::EthereumMainnet, 1))
                .unwrap();
        }
        let delta = block.sccp_execution_write_set_bytes();
        assert!(
            delta
                .windows(field.len())
                .any(|bytes| bytes == field.as_bytes())
        );
        assert_ne!(block.merge_execution_write_set_bytes(), before);
        assert!(block.merge_execution_write_set_bytes().ends_with(&delta));
        assert_eq!(
            delta.last(),
            Some(&0),
            "the removed key retains its deletion tag"
        );
        drop(block);
        assert_eq!(
            world.sccp_destination_pending_generations.view().get(&7),
            Some(&())
        );
        assert_eq!(
            world
                .sccp_reconciliation_due
                .view()
                .get(&(7, SccpNetworkV1::EthereumMainnet, 1)),
            Some(&())
        );
    }
}
#[test]
fn pair_index_members_write_only_when_membership_changes() {
    let storage: Storage<(u32, u32), ()> = [((1, 10), ())].into_iter().collect();
    let mut block = storage.block();
    let mut transaction = block.transaction();
    assert!(!insert_index_member(&mut transaction, &1, &10));
    assert!(!remove_index_member(&mut transaction, &1, &11));
    assert!(!remove_index_member(&mut transaction, &2, &10));
    assert_eq!(
        transaction.touched_entries().len(),
        0,
        "unchanged membership must not copy or touch any index row"
    );
    assert!(insert_index_member(&mut transaction, &1, &11));
    assert!(insert_index_member(&mut transaction, &2, &20));
    assert_eq!(
        index_members(&transaction, &1).copied().collect::<Vec<_>>(),
        [10, 11]
    );
    assert_eq!(
        index_members(&transaction, &2).copied().collect::<Vec<_>>(),
        [20]
    );
    assert!(remove_index_member(&mut transaction, &2, &20));
    assert!(
        !index_contains(&transaction, &2, &20),
        "removed membership leaves the index"
    );
    assert_eq!(transaction.touched_entries().len(), 2);
    transaction.apply();
}

state_test! { sync canonical_merge_cells_follow_actual_transaction_apply_and_drop
    let state = blank_state();
    let header = BlockHeader::new(nonzero!(1_u64), None, None, 0, 0);
    let mut block = state.block(header);
    let hints = vec![Hash::new(b"transaction retained hint")];
    let root = Some(Hash::new(b"transaction retained root"));
    {
        let mut transaction = block.transaction();
        *transaction.world.merge_hint_roots = hints.clone();
        *transaction.world.merge_global_state_root = root;
        // Drop the original transaction; neither canonical value may escape.
    }
    assert!(block.world.merge_hint_roots.is_empty());
    assert_eq!(**block.world.merge_global_state_root, None);
    {
        let mut transaction = block.transaction();
        *transaction.world.merge_hint_roots = hints.clone();
        *transaction.world.merge_global_state_root = root;
        transaction.apply();
    }
    assert_eq!(block.world.merge_hint_roots.as_slice(), hints.as_slice());
    assert_eq!(**block.world.merge_global_state_root, root);
    {
        let mut transaction = block.transaction();
        transaction.world.merge_hint_roots.clear();
        *transaction.world.merge_global_state_root = None;
        transaction.apply();
    }
    assert!(block.world.merge_hint_roots.is_empty());
    assert_eq!(**block.world.merge_global_state_root, None);
}
